window.MG_LAZY_DATA["data/lazy/owner-courses/b362-2acf4cc84e5c2e23.json"]={sha256:"2acf4cc84e5c2e23aadbab1416ce619d84e0ff2fb9b6b2e6aa38f27a7bcd5993",value:{"id":"b362","title":"牽引變電所整合","titleEn":"Traction-substation integration","category":"rail","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","summary":"牽引變電所整合以「牽引變壓整流負載與保護邊界」為主線，將十個物理或系統問題拆成機制、計算、驗證與診斷。變電所整合需要分辨電壓層級、交流相量、直流回路與能量帳，額定設備容量不能直接代表供電區間可同時支援的列車數。每個單元附帶可重算的假想數據與敏感度，學員需提交帶單位的工作表、可區分失效的證據及模型邊界。","summaryEn":"This course develops traction transformation rectification load and protection boundaries through ten physical or systems questions, each studied through mechanism, calculation, verification and diagnosis. Substation integration distinguishes voltage levels, AC phasors, DC circuits and energy balances; equipment ratings do not directly establish how many trains a feeding section supports. Every unit contains reproducible assumed inputs and a sensitivity calculation. Learners submit a worksheet with units, discriminating evidence for failures, and explicit model boundaries.","scope":"依公開工程原理、官方資料與規範架構編寫的原創教學；步驟是可驗證的學習任務與假想算例，不是設計圖說、施工計畫、軌道進入、牽引供電隔離或列車營運許可，也不是任何專案的設計文件。數值均為教學假設或公開資料，實際工程須由合格技師依規範與實測資料重新計算並簽證。","scopeEn":"Original teaching built from public engineering principles, official sources and code frameworks. Steps are verifiable learning tasks and hypothetical exercises, not design drawings, method statements, track-access, traction-power isolation or train-operation permits, or any project's design documents. Numbers are teaching assumptions or public data; real work must be recalculated and certified by qualified engineers using codes and measured data.","subcategory":"rail-power","subcategoryTitle":"牽引供電與受流","subcategoryTitleEn":"Traction power and current collection","learningTrack":"rail","learningSubdiscipline":"rail-power","learningTags":["rail","rail-power","power"],"architectureFamily":"rail-power","architectureNodes":[["公共電網","Public grid"],["變壓整流","Transformer rectifier"],["牽引母線","Traction bus"],["饋線負載","Feeder load"],["保護量測","Protection measurement"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,4],[4,0]],"diagram":{"type":"rail-power","labels":["公共電網","變壓整流","牽引母線","饋線負載","保護量測"],"labelsEn":["Public grid","Transformer rectifier","Traction bus","Feeder load","Protection measurement"],"original":true,"notToScale":true},"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"以下為跨單元的原創假想工作表。先用第一單元定義邊界與單位，再以第二單元檢查另一個控制量，最後用第三單元提出前兩式未涵蓋的另一個檢查問題。原創假想算例，輸入不是現場操作值：primary=25000 V, ratio=25 1；y=primary/ratio=1000 V。只把 primary 增加百分之十，y=1100 V。模型邊界：理想單相變壓器幅值比；上式只代表本單元明列項，不把它視為完整驗證。 原創假想算例，輸入不是現場操作值：Vline=11000 V, Iline=500 A；y=sqrt(3)*Vline*Iline/1e6=9.52628 MVA。只把 Vline 增加百分之十，y=10.4789 MVA。模型邊界：平衡三相正弦系統；上式只代表本單元明列項，不把它視為完整驗證。把兩個算例的單一輸入敏感度放在同一張決策表，說明哪個變化最值得先量測；不可把不同物理量的裸數字直接比較，也不可把任一結果當成實際設備的設計、施工或營運許可。","textEn":"This original worksheet connects the first three units using assumed inputs. Establish boundaries and units with the first unit, examine another controlling quantity with the second, and use the third to pose a separate check outside the first two equations. Original assumed example, not field operating values: primary=25000 V, ratio=25 1; y=primary/ratio=1000 V. Increasing only primary with a ten-percent increase gives y=1100 V. Boundary: Ideal single-phase transformer magnitude ratio; this equation represents only the explicitly listed term and is not a complete verification. Original assumed example, not field operating values: Vline=11000 V, Iline=500 A; y=sqrt(3)*Vline*Iline/1e6=9.52628 MVA. Increasing only Vline with a ten-percent increase gives y=10.4789 MVA. Boundary: Balanced sinusoidal three-phase system; this equation represents only the explicitly listed term and is not a complete verification.Put both single-input sensitivities in one decision table and explain which change most deserves measurement. Do not compare bare numbers with different physical dimensions, and do not treat any result as design approval, a construction procedure or operating permission.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"depth":5,"languageCoverage":["zh-TW","en"],"simulationOnly":true,"educationEdition":16,"enrichmentVersion":16,"stages":[{"id":"b362-v16-s1","title":"變壓器電壓比與三相視在功率","titleEn":"Transformer voltage ratio & Three-phase apparent power","description":"本階段聚焦「變壓器電壓比」與「三相視在功率」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Transformer voltage ratio\" and \"Three-phase apparent power\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b362-v16-01","title":"變壓器電壓比：機制與系統路徑","titleEn":"Transformer voltage ratio: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":[],"objective":"說明「變壓器電壓比」如何影響牽引變電所整合的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Transformer voltage ratio” governs forces, deformation, flow or signals in “Traction-substation integration”, and map the relevant inputs, transfer paths and boundaries.","instruction":"理想匝數比改變電壓而近似保存功率。本模型把 primary 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 1100 V。這個比較描述明列方程的局部敏感度，不能把相關變數也一起改變後仍稱為相同測試。理想單相變壓器幅值比。使用次側空載電壓與匝比作量測證據，才能檢查方程是否對應此處的實際物理量；負載壓降使實測值偏離理想比，因此應把該原因與量測偏差分開。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「變壓器電壓比」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"An ideal turns ratio changes voltage while approximately conserving power. In this model, primary is deliberately changed while every other input is held fixed. A ten-percent increase means the output increases to 1100 V. This comparison describes the sensitivity of the stated equation; changing correlated variables at the same time would be a different experiment. Ideal single-phase transformer magnitude ratio. Use secondary no-load voltage and turns ratio as measurement evidence that the equation represents the intended physical quantity. Load voltage drop separates measured voltage from the ideal ratio; separate that causal mechanism from bias in the measurement chain. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Transformer voltage ratio” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入不是現場操作值：primary=25000 V, ratio=25 1；y=primary/ratio=1000 V。","observationEn":"Order-of-magnitude cue: Original assumed example, not field operating values: primary=25000 V, ratio=25 1; y=primary/ratio=1000 V.","failure":"常見誤解：「本單元絕不可能出現這種失效：負載壓降使實測值偏離理想比」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"This unit cannot exhibit the following failure: Load voltage drop separates measured voltage from the ideal ratio.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「變壓器電壓比」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Transformer voltage ratio”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b362-v16-01-k1","title":"變壓器電壓比","titleEn":"Transformer voltage ratio","text":"理想匝數比改變電壓而近似保存功率。本模型把 primary 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 1100 V。","textEn":"An ideal turns ratio changes voltage while approximately conserving power. In this model, primary is deliberately changed while every other input is held fixed.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：本單元絕不可能出現這種失效：負載壓降使實測值偏離理想比 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: This unit cannot exhibit the following failure: Load voltage drop separates measured voltage from the ideal ratio. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"關於「變壓器電壓比」，下列哪一項敘述正確？","questionEn":"Which statement about \"Transformer voltage ratio\" is correct?","options":["本單元絕不可能出現這種失效：負載壓降使實測值偏離理想比","理想匝數比改變電壓而近似保存功率。","本單元絕不可能出現這種失效：混用相電壓與線電壓造成比例誤差"],"optionsEn":["This unit cannot exhibit the following failure: Load voltage drop separates measured voltage from the ideal ratio.","An ideal turns ratio changes voltage while approximately conserving power.","This unit cannot exhibit the following failure: Mixing phase and line voltage creates a scale error."],"answer":1,"explanation":"理想匝數比改變電壓而近似保存功率。 其餘選項是常見誤解。","explanationEn":"An ideal turns ratio changes voltage while approximately conserving power. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":1},{"id":"b362-v16-02","title":"變壓器電壓比：定量估算","titleEn":"Transformer voltage ratio: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-01"],"objective":"以數值模型估算「變壓器電壓比」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Transformer voltage ratio” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入不是現場操作值：primary=25000 V, ratio=25 1；y=primary/ratio=1000 V。只把 primary 增加百分之十，y=1100 V。模型邊界：理想單相變壓器幅值比；上式只代表本單元明列項，不把它視為完整驗證。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original assumed example, not field operating values: primary=25000 V, ratio=25 1; y=primary/ratio=1000 V. Increasing only primary with a ten-percent increase gives y=1100 V. Boundary: Ideal single-phase transformer magnitude ratio; this equation represents only the explicitly listed term and is not a complete verification. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：本單元以次側空載電壓與匝比區分模型與觀察，先用隔離低壓縮比變壓器建立基準，再保留相同量測位置與工況重複比較。","observationEn":"How to cross-check: Use secondary no-load voltage and turns ratio to distinguish the model from observation in this unit.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b362-v16-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入不是現場操作值：primary=25000 V, ratio=25 1；y=primary/ratio=1000 V。只把 primary 增加百分之十，y=1100 V。模型邊界：理想單相變壓器幅值比；上式只代表本單元明列項，不把它視為完整驗證。","textEn":"Original assumed example, not field operating values: primary=25000 V, ratio=25 1; y=primary/ratio=1000 V. Increasing only primary with a ten-percent increase gives y=1100 V. Boundary: Ideal single-phase transformer magnitude ratio; this equation represents only the explicitly listed term and is not a complete verification.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"依「變壓器電壓比」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Transformer voltage ratio\", which statement holds?","options":["本單元絕不可能出現這種失效：換相壓降與元件壓降使真值較低","本單元絕不可能出現這種失效：輔助負載遺漏會高估整站效率","原創假想算例，輸入不是現場操作值：primary=25000 V, ratio=25 1；y=primary/ratio=1000 V。"],"optionsEn":["This unit cannot exhibit the following failure: Commutation and device drops reduce the actual value.","This unit cannot exhibit the following failure: Omitted auxiliary loads overstate station efficiency.","Original assumed example, not field operating values: primary=25000 V, ratio=25 1; y=primary/ratio=1000 V."],"answer":2,"explanation":"原創假想算例，輸入不是現場操作值：primary=25000 V, ratio=25 1；y=primary/ratio=1000 V。 重算時請保留單位。","explanationEn":"Original assumed example, not field operating values: primary=25000 V, ratio=25 1; y=primary/ratio=1000 V. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":2},{"id":"b362-v16-03","title":"變壓器電壓比：試驗與驗證","titleEn":"Transformer voltage ratio: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「變壓器電壓比」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Transformer voltage ratio” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"本單元以次側空載電壓與匝比區分模型與觀察，先用隔離低壓縮比變壓器建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「變壓器電壓比」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use secondary no-load voltage and turns ratio to distinguish the model from observation in this unit. Establish a baseline using isolated low-voltage scaled transformer, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Transformer voltage ratio. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：重算「變壓器電壓比」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出理想單相變壓器幅值比如何限制結論。接著設計一組符合模型及一組由負載壓降使實測值偏離理想比造成偏離的合成觀察，以次側空載電壓與匝比說明哪個證據能分辨兩者，保留單位及有效位數。","observationEn":"Site practice: Recalculate the baseline and specified single-input perturbation for Transformer voltage ratio, plot the input-output relationship, and explain the limiting assumption: Ideal single-phase transformer magnitude ratio. Construct one synthetic observation consistent with the model and another affected by this failure: Load voltage drop separates measured voltage from the ideal ratio. Explain which evidence in secondary no-load voltage and turns ratio distinguishes them, keeping units and justified significant figures throughout.","failure":"注意干擾：負載壓降使實測值偏離理想比。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Load voltage drop separates measured voltage from the ideal ratio. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b362-v16-03-k1","title":"驗證方法","titleEn":"Verification method","text":"本單元以次側空載電壓與匝比區分模型與觀察，先用隔離低壓縮比變壓器建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「變壓器電壓比」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。","textEn":"Use secondary no-load voltage and turns ratio to distinguish the model from observation in this unit. Establish a baseline using isolated low-voltage scaled transformer, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Transformer voltage ratio. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-03-k2","title":"現場實務","titleEn":"Site practice","text":"重算「變壓器電壓比」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出理想單相變壓器幅值比如何限制結論。接著設計一組符合模型及一組由負載壓降使實測值偏離理想比造成偏離的合成觀察，以次側空載電壓與匝比說明哪個證據能分辨兩者，保留單位及有效位數。","textEn":"Recalculate the baseline and specified single-input perturbation for Transformer voltage ratio, plot the input-output relationship, and explain the limiting assumption: Ideal single-phase transformer magnitude ratio. Construct one synthetic observation consistent with the model and another affected by this failure: Load voltage drop separates measured voltage from the ideal ratio. Explain which evidence in secondary no-load voltage and turns ratio distinguishes them, keeping units and justified significant figures throughout.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"要驗證「變壓器電壓比」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Transformer voltage ratio\"?","options":["本單元以次側空載電壓與匝比區分模型與觀察，先用隔離低壓縮比變壓器建立基準，再保留相同量測位置與工況重複比較。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","本單元絕不可能出現這種失效：忽略源阻抗會得到不合理無限電流"],"optionsEn":["Use secondary no-load voltage and turns ratio to distinguish the model from observation in this unit.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","This unit cannot exhibit the following failure: Omitting source impedance implies unphysical infinite current."],"answer":0,"explanation":"本單元以次側空載電壓與匝比區分模型與觀察，先用隔離低壓縮比變壓器建立基準，再保留相同量測位置與工況重複比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use secondary no-load voltage and turns ratio to distinguish the model from observation in this unit. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":3},{"id":"b362-v16-04","title":"變壓器電壓比：失效診斷","titleEn":"Transformer voltage ratio: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-03"],"objective":"從症狀倒推「變壓器電壓比」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Transformer voltage ratio” and propose discriminating checks, corrective actions and prevention.","instruction":"負載壓降使實測值偏離理想比。這個失效與「變壓器電壓比」的量測偏差可能產生相似表象，因此必須同時檢查次側空載電壓與匝比，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Load voltage drop separates measured voltage from the ideal ratio. This failure and a measurement bias in Transformer voltage ratio can produce similar symptoms. Cross-check secondary no-load voltage and turns ratio rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：使用次側空載電壓與匝比作量測證據，才能檢查方程是否對應此處的實際物理量；負載壓降使實測值偏離理想比，因此應把該原因與量測偏差分開。","observationEn":"Link to the mechanism: Load voltage drop separates measured voltage from the ideal ratio; separate that causal mechanism from bias in the measurement chain.","failure":"誤判風險：若相信「本單元絕不可能出現這種失效：負載壓降使實測值偏離理想比」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"This unit cannot exhibit the following failure: Load voltage drop separates measured voltage from the ideal ratio.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b362-v16-04-k1","title":"失效模式","titleEn":"Failure mode","text":"負載壓降使實測值偏離理想比。這個失效與「變壓器電壓比」的量測偏差可能產生相似表象，因此必須同時檢查次側空載電壓與匝比，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。","textEn":"Load voltage drop separates measured voltage from the ideal ratio. This failure and a measurement bias in Transformer voltage ratio can produce similar symptoms. Cross-check secondary no-load voltage and turns ratio rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"在「變壓器電壓比」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Transformer voltage ratio\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","負載壓降使實測值偏離理想比。","本單元絕不可能出現這種失效：混用相電壓與線電壓造成比例誤差"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Load voltage drop separates measured voltage from the ideal ratio.","This unit cannot exhibit the following failure: Mixing phase and line voltage creates a scale error."],"answer":1,"explanation":"負載壓降使實測值偏離理想比。 需以量測區分可能原因。","explanationEn":"Load voltage drop separates measured voltage from the ideal ratio. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":4},{"id":"b362-v16-05","title":"三相視在功率：機制與系統路徑","titleEn":"Three-phase apparent power: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-04"],"objective":"說明「三相視在功率」如何影響牽引變電所整合的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Three-phase apparent power” governs forces, deformation, flow or signals in “Traction-substation integration”, and map the relevant inputs, transfer paths and boundaries.","instruction":"線電壓與線電流的三相關係包含根號三。本模型把 Vline 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 10.4789 MVA。這個比較描述明列方程的局部敏感度，不能把相關變數也一起改變後仍稱為相同測試。平衡三相正弦系統。使用三相電壓電流與平衡度作量測證據，才能檢查方程是否對應此處的實際物理量；混用相電壓與線電壓造成比例誤差，因此應把該原因與量測偏差分開。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「三相視在功率」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"The three-phase relation between line voltage and line current includes square root of three. In this model, Vline is deliberately changed while every other input is held fixed. A ten-percent increase means the output increases to 10.4789 MVA. This comparison describes the sensitivity of the stated equation; changing correlated variables at the same time would be a different experiment. Balanced sinusoidal three-phase system. Use three-phase voltage, current and balance as measurement evidence that the equation represents the intended physical quantity. Mixing phase and line voltage creates a scale error; separate that causal mechanism from bias in the measurement chain. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Three-phase apparent power” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入不是現場操作值：Vline=11000 V, Iline=500 A；y=sqrt(3)*Vline*Iline/1e6=9.52628 MVA。","observationEn":"Order-of-magnitude cue: Original assumed example, not field operating values: Vline=11000 V, Iline=500 A; y=sqrt(3)*Vline*Iline/1e6=9.52628 MVA.","failure":"常見誤解：「本單元絕不可能出現這種失效：混用相電壓與線電壓造成比例誤差」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"This unit cannot exhibit the following failure: Mixing phase and line voltage creates a scale error.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「三相視在功率」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Three-phase apparent power”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b362-v16-05-k1","title":"三相視在功率","titleEn":"Three-phase apparent power","text":"線電壓與線電流的三相關係包含根號三。本模型把 Vline 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 10.4789 MVA。","textEn":"The three-phase relation between line voltage and line current includes square root of three. In this model, Vline is deliberately changed while every other input is held fixed.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：本單元絕不可能出現這種失效：混用相電壓與線電壓造成比例誤差 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: This unit cannot exhibit the following failure: Mixing phase and line voltage creates a scale error. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"關於「三相視在功率」，下列哪一項敘述正確？","questionEn":"Which statement about \"Three-phase apparent power\" is correct?","options":["本單元絕不可能出現這種失效：混用相電壓與線電壓造成比例誤差","本單元絕不可能出現這種失效：畸變功因不能只用相位角描述","線電壓與線電流的三相關係包含根號三。"],"optionsEn":["This unit cannot exhibit the following failure: Mixing phase and line voltage creates a scale error.","This unit cannot exhibit the following failure: Distortion power factor is not described by phase angle alone.","The three-phase relation between line voltage and line current includes square root of three."],"answer":2,"explanation":"線電壓與線電流的三相關係包含根號三。 其餘選項是常見誤解。","explanationEn":"The three-phase relation between line voltage and line current includes square root of three. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":5},{"id":"b362-v16-06","title":"三相視在功率：定量估算","titleEn":"Three-phase apparent power: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-05"],"objective":"以數值模型估算「三相視在功率」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Three-phase apparent power” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入不是現場操作值：Vline=11000 V, Iline=500 A；y=sqrt(3)*Vline*Iline/1e6=9.52628 MVA。只把 Vline 增加百分之十，y=10.4789 MVA。模型邊界：平衡三相正弦系統；上式只代表本單元明列項，不把它視為完整驗證。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original assumed example, not field operating values: Vline=11000 V, Iline=500 A; y=sqrt(3)*Vline*Iline/1e6=9.52628 MVA. Increasing only Vline with a ten-percent increase gives y=10.4789 MVA. Boundary: Balanced sinusoidal three-phase system; this equation represents only the explicitly listed term and is not a complete verification. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：本單元以三相電壓電流與平衡度區分模型與觀察，先用合成三相功率分析資料建立基準，再保留相同量測位置與工況重複比較。","observationEn":"How to cross-check: Use three-phase voltage, current and balance to distinguish the model from observation in this unit.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b362-v16-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入不是現場操作值：Vline=11000 V, Iline=500 A；y=sqrt(3)*Vline*Iline/1e6=9.52628 MVA。只把 Vline 增加百分之十，y=10.4789 MVA。模型邊界：平衡三相正弦系統；上式只代表本單元明列項，不把它視為完整驗證。","textEn":"Original assumed example, not field operating values: Vline=11000 V, Iline=500 A; y=sqrt(3)*Vline*Iline/1e6=9.52628 MVA. Increasing only Vline with a ten-percent increase gives y=10.4789 MVA. Boundary: Balanced sinusoidal three-phase system; this equation represents only the explicitly listed term and is not a complete verification.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"依「三相視在功率」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Three-phase apparent power\", which statement holds?","options":["原創假想算例，輸入不是現場操作值：Vline=11000 V, Iline=500 A。","本單元絕不可能出現這種失效：只計去路導線會漏掉回流壓降","本單元絕不可能出現這種失效：時窗對齊不同可改變記錄尖峰"],"optionsEn":["Original assumed example, not field operating values: Vline=11000 V, Iline=500 A; y=sqrt(3)*Vline*Iline/1e6=9.52628 MVA.","This unit cannot exhibit the following failure: Counting only the outgoing conductor misses return drop.","This unit cannot exhibit the following failure: Different window alignment changes recorded peaks."],"answer":0,"explanation":"原創假想算例，輸入不是現場操作值：Vline=11000 V, Iline=500 A；y=sqrt(3)*Vline*Iline/1e6=9.52628 MVA。 重算時請保留單位。","explanationEn":"Original assumed example, not field operating values: Vline=11000 V, Iline=500 A; y=sqrt(3)*Vline*Iline/1e6=9.52628 MVA. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":6},{"id":"b362-v16-07","title":"三相視在功率：試驗與驗證","titleEn":"Three-phase apparent power: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「三相視在功率」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Three-phase apparent power” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"本單元以三相電壓電流與平衡度區分模型與觀察，先用合成三相功率分析資料建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「三相視在功率」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use three-phase voltage, current and balance to distinguish the model from observation in this unit. Establish a baseline using synthetic three-phase power-analyzer data, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Three-phase apparent power. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：重算「三相視在功率」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出平衡三相正弦系統如何限制結論。接著設計一組符合模型及一組由混用相電壓與線電壓造成比例誤差造成偏離的合成觀察，以三相電壓電流與平衡度說明哪個證據能分辨兩者，保留單位及有效位數。","observationEn":"Site practice: Recalculate the baseline and specified single-input perturbation for Three-phase apparent power, plot the input-output relationship, and explain the limiting assumption: Balanced sinusoidal three-phase system. Construct one synthetic observation consistent with the model and another affected by this failure: Mixing phase and line voltage creates a scale error. Explain which evidence in three-phase voltage, current and balance distinguishes them, keeping units and justified significant figures throughout.","failure":"注意干擾：混用相電壓與線電壓造成比例誤差。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Mixing phase and line voltage creates a scale error. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b362-v16-07-k1","title":"驗證方法","titleEn":"Verification method","text":"本單元以三相電壓電流與平衡度區分模型與觀察，先用合成三相功率分析資料建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「三相視在功率」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。","textEn":"Use three-phase voltage, current and balance to distinguish the model from observation in this unit. Establish a baseline using synthetic three-phase power-analyzer data, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Three-phase apparent power. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-07-k2","title":"現場實務","titleEn":"Site practice","text":"重算「三相視在功率」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出平衡三相正弦系統如何限制結論。接著設計一組符合模型及一組由混用相電壓與線電壓造成比例誤差造成偏離的合成觀察，以三相電壓電流與平衡度說明哪個證據能分辨兩者，保留單位及有效位數。","textEn":"Recalculate the baseline and specified single-input perturbation for Three-phase apparent power, plot the input-output relationship, and explain the limiting assumption: Balanced sinusoidal three-phase system. Construct one synthetic observation consistent with the model and another affected by this failure: Mixing phase and line voltage creates a scale error. Explain which evidence in three-phase voltage, current and balance distinguishes them, keeping units and justified significant figures throughout.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"要驗證「三相視在功率」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Three-phase apparent power\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","本單元以三相電壓電流與平衡度區分模型與觀察，先用合成三相功率分析資料建立基準，再保留相同量測位置與工況重複比較。","本單元絕不可能出現這種失效：鬆動接點會提高局部發熱"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Use three-phase voltage, current and balance to distinguish the model from observation in this unit.","This unit cannot exhibit the following failure: A loose joint raises local heating."],"answer":1,"explanation":"本單元以三相電壓電流與平衡度區分模型與觀察，先用合成三相功率分析資料建立基準，再保留相同量測位置與工況重複比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use three-phase voltage, current and balance to distinguish the model from observation in this unit. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":7},{"id":"b362-v16-08","title":"三相視在功率：失效診斷","titleEn":"Three-phase apparent power: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-07"],"objective":"從症狀倒推「三相視在功率」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Three-phase apparent power” and propose discriminating checks, corrective actions and prevention.","instruction":"混用相電壓與線電壓造成比例誤差。這個失效與「三相視在功率」的量測偏差可能產生相似表象，因此必須同時檢查三相電壓電流與平衡度，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Mixing phase and line voltage creates a scale error. This failure and a measurement bias in Three-phase apparent power can produce similar symptoms. Cross-check three-phase voltage, current and balance rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：使用三相電壓電流與平衡度作量測證據，才能檢查方程是否對應此處的實際物理量；混用相電壓與線電壓造成比例誤差，因此應把該原因與量測偏差分開。","observationEn":"Link to the mechanism: Mixing phase and line voltage creates a scale error; separate that causal mechanism from bias in the measurement chain.","failure":"誤判風險：若相信「本單元絕不可能出現這種失效：混用相電壓與線電壓造成比例誤差」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"This unit cannot exhibit the following failure: Mixing phase and line voltage creates a scale error.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b362-v16-08-k1","title":"失效模式","titleEn":"Failure mode","text":"混用相電壓與線電壓造成比例誤差。這個失效與「三相視在功率」的量測偏差可能產生相似表象，因此必須同時檢查三相電壓電流與平衡度，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。","textEn":"Mixing phase and line voltage creates a scale error. This failure and a measurement bias in Three-phase apparent power can produce similar symptoms. Cross-check three-phase voltage, current and balance rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"在「三相視在功率」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Three-phase apparent power\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","本單元絕不可能出現這種失效：畸變功因不能只用相位角描述","混用相電壓與線電壓造成比例誤差。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","This unit cannot exhibit the following failure: Distortion power factor is not described by phase angle alone.","Mixing phase and line voltage creates a scale error."],"answer":2,"explanation":"混用相電壓與線電壓造成比例誤差。 需以量測區分可能原因。","explanationEn":"Mixing phase and line voltage creates a scale error. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":8}],"order":1},{"id":"b362-v16-s2","title":"實功率與功因與整流理想平均電壓","titleEn":"Real power and power factor & Ideal rectifier mean voltage","description":"本階段聚焦「實功率與功因」與「整流理想平均電壓」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Real power and power factor\" and \"Ideal rectifier mean voltage\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b362-v16-09","title":"實功率與功因：機制與系統路徑","titleEn":"Real power and power factor: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-08"],"objective":"說明「實功率與功因」如何影響牽引變電所整合的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Real power and power factor” governs forces, deformation, flow or signals in “Traction-substation integration”, and map the relevant inputs, transfer paths and boundaries.","instruction":"功率因數把視在功率分成可用實功部分。本模型把 S 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 9.9 MW。這個比較描述明列方程的局部敏感度，不能把相關變數也一起改變後仍稱為相同測試。已知總功率因數。使用有功無功與波形作量測證據，才能檢查方程是否對應此處的實際物理量；畸變功因不能只用相位角描述，因此應把該原因與量測偏差分開。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「實功率與功因」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Power factor relates apparent power to real power. In this model, S is deliberately changed while every other input is held fixed. A ten-percent increase means the output increases to 9.9 MW. This comparison describes the sensitivity of the stated equation; changing correlated variables at the same time would be a different experiment. Known total power factor. Use real/reactive power and waveforms as measurement evidence that the equation represents the intended physical quantity. Distortion power factor is not described by phase angle alone; separate that causal mechanism from bias in the measurement chain. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Real power and power factor” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入不是現場操作值：S=10 MVA, pf=0.9 1；y=S*pf=9 MW。","observationEn":"Order-of-magnitude cue: Original assumed example, not field operating values: S=10 MVA, pf=0.9 1; y=S*pf=9 MW.","failure":"常見誤解：「本單元絕不可能出現這種失效：畸變功因不能只用相位角描述」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"This unit cannot exhibit the following failure: Distortion power factor is not described by phase angle alone.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「實功率與功因」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Real power and power factor”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b362-v16-09-k1","title":"實功率與功因","titleEn":"Real power and power factor","text":"功率因數把視在功率分成可用實功部分。本模型把 S 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 9.9 MW。","textEn":"Power factor relates apparent power to real power. In this model, S is deliberately changed while every other input is held fixed.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：本單元絕不可能出現這種失效：畸變功因不能只用相位角描述 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: This unit cannot exhibit the following failure: Distortion power factor is not described by phase angle alone. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"關於「實功率與功因」，下列哪一項敘述正確？","questionEn":"Which statement about \"Real power and power factor\" is correct?","options":["功率因數把視在功率分成可用實功部分。","本單元絕不可能出現這種失效：畸變功因不能只用相位角描述","本單元絕不可能出現這種失效：換相壓降與元件壓降使真值較低"],"optionsEn":["Power factor relates apparent power to real power.","This unit cannot exhibit the following failure: Distortion power factor is not described by phase angle alone.","This unit cannot exhibit the following failure: Commutation and device drops reduce the actual value."],"answer":0,"explanation":"功率因數把視在功率分成可用實功部分。 其餘選項是常見誤解。","explanationEn":"Power factor relates apparent power to real power. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":9},{"id":"b362-v16-10","title":"實功率與功因：定量估算","titleEn":"Real power and power factor: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-09"],"objective":"以數值模型估算「實功率與功因」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Real power and power factor” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入不是現場操作值：S=10 MVA, pf=0.9 1；y=S*pf=9 MW。只把 S 增加百分之十，y=9.9 MW。模型邊界：已知總功率因數；上式只代表本單元明列項，不把它視為完整驗證。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original assumed example, not field operating values: S=10 MVA, pf=0.9 1; y=S*pf=9 MW. Increasing only S with a ten-percent increase gives y=9.9 MW. Boundary: Known total power factor; this equation represents only the explicitly listed term and is not a complete verification. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：本單元以有功無功與波形區分模型與觀察，先用合成功率分析儀輸出建立基準，再保留相同量測位置與工況重複比較。","observationEn":"How to cross-check: Use real/reactive power and waveforms to distinguish the model from observation in this unit.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b362-v16-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入不是現場操作值：S=10 MVA, pf=0.9 1；y=S*pf=9 MW。只把 S 增加百分之十，y=9.9 MW。模型邊界：已知總功率因數；上式只代表本單元明列項，不把它視為完整驗證。","textEn":"Original assumed example, not field operating values: S=10 MVA, pf=0.9 1; y=S*pf=9 MW. Increasing only S with a ten-percent increase gives y=9.9 MW. Boundary: Known total power factor; this equation represents only the explicitly listed term and is not a complete verification.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"依「實功率與功因」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Real power and power factor\", which statement holds?","options":["本單元絕不可能出現這種失效：輔助負載遺漏會高估整站效率","原創假想算例，輸入不是現場操作值：S=10 MVA, pf=0.9 1；y=S*pf=9 MW。","本單元絕不可能出現這種失效：忽略源阻抗會得到不合理無限電流"],"optionsEn":["This unit cannot exhibit the following failure: Omitted auxiliary loads overstate station efficiency.","Original assumed example, not field operating values: S=10 MVA, pf=0.9 1; y=S*pf=9 MW.","This unit cannot exhibit the following failure: Omitting source impedance implies unphysical infinite current."],"answer":1,"explanation":"原創假想算例，輸入不是現場操作值：S=10 MVA, pf=0.9 1；y=S*pf=9 MW。 重算時請保留單位。","explanationEn":"Original assumed example, not field operating values: S=10 MVA, pf=0.9 1; y=S*pf=9 MW. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":10},{"id":"b362-v16-11","title":"實功率與功因：試驗與驗證","titleEn":"Real power and power factor: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「實功率與功因」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Real power and power factor” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"本單元以有功無功與波形區分模型與觀察，先用合成功率分析儀輸出建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「實功率與功因」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use real/reactive power and waveforms to distinguish the model from observation in this unit. Establish a baseline using synthetic power-analyzer output, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Real power and power factor. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：重算「實功率與功因」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出已知總功率因數如何限制結論。接著設計一組符合模型及一組由畸變功因不能只用相位角描述造成偏離的合成觀察，以有功無功與波形說明哪個證據能分辨兩者，保留單位及有效位數。","observationEn":"Site practice: Recalculate the baseline and specified single-input perturbation for Real power and power factor, plot the input-output relationship, and explain the limiting assumption: Known total power factor. Construct one synthetic observation consistent with the model and another affected by this failure: Distortion power factor is not described by phase angle alone. Explain which evidence in real/reactive power and waveforms distinguishes them, keeping units and justified significant figures throughout.","failure":"注意干擾：畸變功因不能只用相位角描述。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Distortion power factor is not described by phase angle alone. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b362-v16-11-k1","title":"驗證方法","titleEn":"Verification method","text":"本單元以有功無功與波形區分模型與觀察，先用合成功率分析儀輸出建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「實功率與功因」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。","textEn":"Use real/reactive power and waveforms to distinguish the model from observation in this unit. Establish a baseline using synthetic power-analyzer output, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Real power and power factor. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-11-k2","title":"現場實務","titleEn":"Site practice","text":"重算「實功率與功因」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出已知總功率因數如何限制結論。接著設計一組符合模型及一組由畸變功因不能只用相位角描述造成偏離的合成觀察，以有功無功與波形說明哪個證據能分辨兩者，保留單位及有效位數。","textEn":"Recalculate the baseline and specified single-input perturbation for Real power and power factor, plot the input-output relationship, and explain the limiting assumption: Known total power factor. Construct one synthetic observation consistent with the model and another affected by this failure: Distortion power factor is not described by phase angle alone. Explain which evidence in real/reactive power and waveforms distinguishes them, keeping units and justified significant figures throughout.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"要驗證「實功率與功因」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Real power and power factor\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","本單元絕不可能出現這種失效：有容量但無連通路徑仍無法供電","本單元以有功無功與波形區分模型與觀察，先用合成功率分析儀輸出建立基準，再保留相同量測位置與工況重複比較。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","This unit cannot exhibit the following failure: Capacity without connectivity cannot supply the load.","Use real/reactive power and waveforms to distinguish the model from observation in this unit."],"answer":2,"explanation":"本單元以有功無功與波形區分模型與觀察，先用合成功率分析儀輸出建立基準，再保留相同量測位置與工況重複比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use real/reactive power and waveforms to distinguish the model from observation in this unit. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":11},{"id":"b362-v16-12","title":"實功率與功因：失效診斷","titleEn":"Real power and power factor: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-11"],"objective":"從症狀倒推「實功率與功因」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Real power and power factor” and propose discriminating checks, corrective actions and prevention.","instruction":"畸變功因不能只用相位角描述。這個失效與「實功率與功因」的量測偏差可能產生相似表象，因此必須同時檢查有功無功與波形，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Distortion power factor is not described by phase angle alone. This failure and a measurement bias in Real power and power factor can produce similar symptoms. Cross-check real/reactive power and waveforms rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：使用有功無功與波形作量測證據，才能檢查方程是否對應此處的實際物理量；畸變功因不能只用相位角描述，因此應把該原因與量測偏差分開。","observationEn":"Link to the mechanism: Distortion power factor is not described by phase angle alone; separate that causal mechanism from bias in the measurement chain.","failure":"誤判風險：若相信「本單元絕不可能出現這種失效：畸變功因不能只用相位角描述」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"This unit cannot exhibit the following failure: Distortion power factor is not described by phase angle alone.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b362-v16-12-k1","title":"失效模式","titleEn":"Failure mode","text":"畸變功因不能只用相位角描述。這個失效與「實功率與功因」的量測偏差可能產生相似表象，因此必須同時檢查有功無功與波形，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。","textEn":"Distortion power factor is not described by phase angle alone. This failure and a measurement bias in Real power and power factor can produce similar symptoms. Cross-check real/reactive power and waveforms rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"在「實功率與功因」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Real power and power factor\" shows distress, which diagnosis is most reasonable?","options":["畸變功因不能只用相位角描述。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","本單元絕不可能出現這種失效：換相壓降與元件壓降使真值較低"],"optionsEn":["Distortion power factor is not described by phase angle alone.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","This unit cannot exhibit the following failure: Commutation and device drops reduce the actual value."],"answer":0,"explanation":"畸變功因不能只用相位角描述。 需以量測區分可能原因。","explanationEn":"Distortion power factor is not described by phase angle alone. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":12},{"id":"b362-v16-13","title":"整流理想平均電壓：機制與系統路徑","titleEn":"Ideal rectifier mean voltage: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-12"],"objective":"說明「整流理想平均電壓」如何影響牽引變電所整合的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Ideal rectifier mean voltage” governs forces, deformation, flow or signals in “Traction-substation integration”, and map the relevant inputs, transfer paths and boundaries.","instruction":"六脈波理想整流平均值取決於交流線電壓。本模型把 Vll 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 891.313 V。這個比較描述明列方程的局部敏感度，不能把相關變數也一起改變後仍稱為相同測試。連續電流理想三相二極體橋。使用直流均值與交流線電壓作量測證據，才能檢查方程是否對應此處的實際物理量；換相壓降與元件壓降使真值較低，因此應把該原因與量測偏差分開。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「整流理想平均電壓」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Ideal six-pulse mean DC voltage depends on AC line voltage. In this model, Vll is deliberately changed while every other input is held fixed. A ten-percent increase means the output increases to 891.313 V. This comparison describes the sensitivity of the stated equation; changing correlated variables at the same time would be a different experiment. Ideal three-phase diode bridge with continuous current. Use DC mean and AC line voltage as measurement evidence that the equation represents the intended physical quantity. Commutation and device drops reduce the actual value; separate that causal mechanism from bias in the measurement chain. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Ideal rectifier mean voltage” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入不是現場操作值：Vll=600 V；y=3*sqrt(2)/pi*Vll=810.285 V。","observationEn":"Order-of-magnitude cue: Original assumed example, not field operating values: Vll=600 V; y=3*sqrt(2)/pi*Vll=810.285 V.","failure":"常見誤解：「本單元絕不可能出現這種失效：換相壓降與元件壓降使真值較低」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"This unit cannot exhibit the following failure: Commutation and device drops reduce the actual value.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「整流理想平均電壓」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Ideal rectifier mean voltage”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b362-v16-13-k1","title":"整流理想平均電壓","titleEn":"Ideal rectifier mean voltage","text":"六脈波理想整流平均值取決於交流線電壓。本模型把 Vll 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 891.313 V。","textEn":"Ideal six-pulse mean DC voltage depends on AC line voltage. In this model, Vll is deliberately changed while every other input is held fixed.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：本單元絕不可能出現這種失效：換相壓降與元件壓降使真值較低 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: This unit cannot exhibit the following failure: Commutation and device drops reduce the actual value. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"關於「整流理想平均電壓」，下列哪一項敘述正確？","questionEn":"Which statement about \"Ideal rectifier mean voltage\" is correct?","options":["本單元絕不可能出現這種失效：換相壓降與元件壓降使真值較低","六脈波理想整流平均值取決於交流線電壓。","本單元絕不可能出現這種失效：只計去路導線會漏掉回流壓降"],"optionsEn":["This unit cannot exhibit the following failure: Commutation and device drops reduce the actual value.","Ideal six-pulse mean DC voltage depends on AC line voltage.","This unit cannot exhibit the following failure: Counting only the outgoing conductor misses return drop."],"answer":1,"explanation":"六脈波理想整流平均值取決於交流線電壓。 其餘選項是常見誤解。","explanationEn":"Ideal six-pulse mean DC voltage depends on AC line voltage. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":13},{"id":"b362-v16-14","title":"整流理想平均電壓：定量估算","titleEn":"Ideal rectifier mean voltage: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-13"],"objective":"以數值模型估算「整流理想平均電壓」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Ideal rectifier mean voltage” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入不是現場操作值：Vll=600 V；y=3*sqrt(2)/pi*Vll=810.285 V。只把 Vll 增加百分之十，y=891.313 V。模型邊界：連續電流理想三相二極體橋；上式只代表本單元明列項，不把它視為完整驗證。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original assumed example, not field operating values: Vll=600 V; y=3*sqrt(2)/pi*Vll=810.285 V. Increasing only Vll with a ten-percent increase gives y=891.313 V. Boundary: Ideal three-phase diode bridge with continuous current; this equation represents only the explicitly listed term and is not a complete verification. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：本單元以直流均值與交流線電壓區分模型與觀察，先用離線整流波形模擬建立基準，再保留相同量測位置與工況重複比較。","observationEn":"How to cross-check: Use DC mean and AC line voltage to distinguish the model from observation in this unit.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b362-v16-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入不是現場操作值：Vll=600 V；y=3*sqrt(2)/pi*Vll=810.285 V。只把 Vll 增加百分之十，y=891.313 V。模型邊界：連續電流理想三相二極體橋；上式只代表本單元明列項，不把它視為完整驗證。","textEn":"Original assumed example, not field operating values: Vll=600 V; y=3*sqrt(2)/pi*Vll=810.285 V. Increasing only Vll with a ten-percent increase gives y=891.313 V. Boundary: Ideal three-phase diode bridge with continuous current; this equation represents only the explicitly listed term and is not a complete verification.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"依「整流理想平均電壓」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Ideal rectifier mean voltage\", which statement holds?","options":["本單元絕不可能出現這種失效：時窗對齊不同可改變記錄尖峰","本單元絕不可能出現這種失效：鬆動接點會提高局部發熱","原創假想算例，輸入不是現場操作值：Vll=600 V；y=3*sqrt(2)/pi*Vll=810.285 V。"],"optionsEn":["This unit cannot exhibit the following failure: Different window alignment changes recorded peaks.","This unit cannot exhibit the following failure: A loose joint raises local heating.","Original assumed example, not field operating values: Vll=600 V; y=3*sqrt(2)/pi*Vll=810.285 V."],"answer":2,"explanation":"原創假想算例，輸入不是現場操作值：Vll=600 V；y=3*sqrt(2)/pi*Vll=810.285 V。 重算時請保留單位。","explanationEn":"Original assumed example, not field operating values: Vll=600 V; y=3*sqrt(2)/pi*Vll=810.285 V. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":14},{"id":"b362-v16-15","title":"整流理想平均電壓：試驗與驗證","titleEn":"Ideal rectifier mean voltage: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「整流理想平均電壓」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Ideal rectifier mean voltage” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"本單元以直流均值與交流線電壓區分模型與觀察，先用離線整流波形模擬建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「整流理想平均電壓」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use DC mean and AC line voltage to distinguish the model from observation in this unit. Establish a baseline using offline rectifier-waveform simulation, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Ideal rectifier mean voltage. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：重算「整流理想平均電壓」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出連續電流理想三相二極體橋如何限制結論。接著設計一組符合模型及一組由換相壓降與元件壓降使真值較低造成偏離的合成觀察，以直流均值與交流線電壓說明哪個證據能分辨兩者，保留單位及有效位數。","observationEn":"Site practice: Recalculate the baseline and specified single-input perturbation for Ideal rectifier mean voltage, plot the input-output relationship, and explain the limiting assumption: Ideal three-phase diode bridge with continuous current. Construct one synthetic observation consistent with the model and another affected by this failure: Commutation and device drops reduce the actual value. Explain which evidence in DC mean and AC line voltage distinguishes them, keeping units and justified significant figures throughout.","failure":"注意干擾：換相壓降與元件壓降使真值較低。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Commutation and device drops reduce the actual value. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b362-v16-15-k1","title":"驗證方法","titleEn":"Verification method","text":"本單元以直流均值與交流線電壓區分模型與觀察，先用離線整流波形模擬建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「整流理想平均電壓」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。","textEn":"Use DC mean and AC line voltage to distinguish the model from observation in this unit. Establish a baseline using offline rectifier-waveform simulation, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Ideal rectifier mean voltage. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-15-k2","title":"現場實務","titleEn":"Site practice","text":"重算「整流理想平均電壓」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出連續電流理想三相二極體橋如何限制結論。接著設計一組符合模型及一組由換相壓降與元件壓降使真值較低造成偏離的合成觀察，以直流均值與交流線電壓說明哪個證據能分辨兩者，保留單位及有效位數。","textEn":"Recalculate the baseline and specified single-input perturbation for Ideal rectifier mean voltage, plot the input-output relationship, and explain the limiting assumption: Ideal three-phase diode bridge with continuous current. Construct one synthetic observation consistent with the model and another affected by this failure: Commutation and device drops reduce the actual value. Explain which evidence in DC mean and AC line voltage distinguishes them, keeping units and justified significant figures throughout.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"要驗證「整流理想平均電壓」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Ideal rectifier mean voltage\"?","options":["本單元以直流均值與交流線電壓區分模型與觀察，先用離線整流波形模擬建立基準，再保留相同量測位置與工況重複比較。","不確定度太難估計，報告中只寫最佳值即可。","本單元絕不可能出現這種失效：負載壓降使實測值偏離理想比"],"optionsEn":["Use DC mean and AC line voltage to distinguish the model from observation in this unit.","Uncertainty is too hard to estimate, so the report may state only the best value.","This unit cannot exhibit the following failure: Load voltage drop separates measured voltage from the ideal ratio."],"answer":0,"explanation":"本單元以直流均值與交流線電壓區分模型與觀察，先用離線整流波形模擬建立基準，再保留相同量測位置與工況重複比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use DC mean and AC line voltage to distinguish the model from observation in this unit. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":15},{"id":"b362-v16-16","title":"整流理想平均電壓：失效診斷","titleEn":"Ideal rectifier mean voltage: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-15"],"objective":"從症狀倒推「整流理想平均電壓」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Ideal rectifier mean voltage” and propose discriminating checks, corrective actions and prevention.","instruction":"換相壓降與元件壓降使真值較低。這個失效與「整流理想平均電壓」的量測偏差可能產生相似表象，因此必須同時檢查直流均值與交流線電壓，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Commutation and device drops reduce the actual value. This failure and a measurement bias in Ideal rectifier mean voltage can produce similar symptoms. Cross-check DC mean and AC line voltage rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：使用直流均值與交流線電壓作量測證據，才能檢查方程是否對應此處的實際物理量；換相壓降與元件壓降使真值較低，因此應把該原因與量測偏差分開。","observationEn":"Link to the mechanism: Commutation and device drops reduce the actual value; separate that causal mechanism from bias in the measurement chain.","failure":"誤判風險：若相信「本單元絕不可能出現這種失效：換相壓降與元件壓降使真值較低」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"This unit cannot exhibit the following failure: Commutation and device drops reduce the actual value.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b362-v16-16-k1","title":"失效模式","titleEn":"Failure mode","text":"換相壓降與元件壓降使真值較低。這個失效與「整流理想平均電壓」的量測偏差可能產生相似表象，因此必須同時檢查直流均值與交流線電壓，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。","textEn":"Commutation and device drops reduce the actual value. This failure and a measurement bias in Ideal rectifier mean voltage can produce similar symptoms. Cross-check DC mean and AC line voltage rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"在「整流理想平均電壓」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Ideal rectifier mean voltage\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","換相壓降與元件壓降使真值較低。","本單元絕不可能出現這種失效：只計去路導線會漏掉回流壓降"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Commutation and device drops reduce the actual value.","This unit cannot exhibit the following failure: Counting only the outgoing conductor misses return drop."],"answer":1,"explanation":"換相壓降與元件壓降使真值較低。 需以量測區分可能原因。","explanationEn":"Commutation and device drops reduce the actual value. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":16}],"order":2},{"id":"b362-v16-s3","title":"供電線路壓降與設備效率能量帳","titleEn":"Feeder voltage drop & Equipment efficiency energy account","description":"本階段聚焦「供電線路壓降」與「設備效率能量帳」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Feeder voltage drop\" and \"Equipment efficiency energy account\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b362-v16-17","title":"供電線路壓降：機制與系統路徑","titleEn":"Feeder voltage drop: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-16"],"objective":"說明「供電線路壓降」如何影響牽引變電所整合的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Feeder voltage drop” governs forces, deformation, flow or signals in “Traction-substation integration”, and map the relevant inputs, transfer paths and boundaries.","instruction":"回路電阻與電流共同消耗受電端電壓。本模型把 I 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 99 V。這個比較描述明列方程的局部敏感度，不能把相關變數也一起改變後仍稱為相同測試。直流穩態完整回路。使用源端與負載端電壓作量測證據，才能檢查方程是否對應此處的實際物理量；只計去路導線會漏掉回流壓降，因此應把該原因與量測偏差分開。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「供電線路壓降」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Loop resistance and current consume receiving-end voltage. In this model, I is deliberately changed while every other input is held fixed. A ten-percent increase means the output increases to 99 V. This comparison describes the sensitivity of the stated equation; changing correlated variables at the same time would be a different experiment. Complete DC loop in steady state. Use source and load terminal voltages as measurement evidence that the equation represents the intended physical quantity. Counting only the outgoing conductor misses return drop; separate that causal mechanism from bias in the measurement chain. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Feeder voltage drop” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入不是現場操作值：I=1500 A, R=0.06 ohm；y=I*R=90 V。","observationEn":"Order-of-magnitude cue: Original assumed example, not field operating values: I=1500 A, R=0.06 ohm; y=I*R=90 V.","failure":"常見誤解：「本單元絕不可能出現這種失效：只計去路導線會漏掉回流壓降」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"This unit cannot exhibit the following failure: Counting only the outgoing conductor misses return drop.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「供電線路壓降」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Feeder voltage drop”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b362-v16-17-k1","title":"供電線路壓降","titleEn":"Feeder voltage drop","text":"回路電阻與電流共同消耗受電端電壓。本模型把 I 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 99 V。","textEn":"Loop resistance and current consume receiving-end voltage. In this model, I is deliberately changed while every other input is held fixed.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：本單元絕不可能出現這種失效：只計去路導線會漏掉回流壓降 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: This unit cannot exhibit the following failure: Counting only the outgoing conductor misses return drop. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"關於「供電線路壓降」，下列哪一項敘述正確？","questionEn":"Which statement about \"Feeder voltage drop\" is correct?","options":["本單元絕不可能出現這種失效：只計去路導線會漏掉回流壓降","本單元絕不可能出現這種失效：輔助負載遺漏會高估整站效率","回路電阻與電流共同消耗受電端電壓。"],"optionsEn":["This unit cannot exhibit the following failure: Counting only the outgoing conductor misses return drop.","This unit cannot exhibit the following failure: Omitted auxiliary loads overstate station efficiency.","Loop resistance and current consume receiving-end voltage."],"answer":2,"explanation":"回路電阻與電流共同消耗受電端電壓。 其餘選項是常見誤解。","explanationEn":"Loop resistance and current consume receiving-end voltage. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":17},{"id":"b362-v16-18","title":"供電線路壓降：定量估算","titleEn":"Feeder voltage drop: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-17"],"objective":"以數值模型估算「供電線路壓降」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Feeder voltage drop” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入不是現場操作值：I=1500 A, R=0.06 ohm；y=I*R=90 V。只把 I 增加百分之十，y=99 V。模型邊界：直流穩態完整回路；上式只代表本單元明列項，不把它視為完整驗證。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original assumed example, not field operating values: I=1500 A, R=0.06 ohm; y=I*R=90 V. Increasing only I with a ten-percent increase gives y=99 V. Boundary: Complete DC loop in steady state; this equation represents only the explicitly listed term and is not a complete verification. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：本單元以源端與負載端電壓區分模型與觀察，先用隔離低壓雙端電壓量測建立基準，再保留相同量測位置與工況重複比較。","observationEn":"How to cross-check: Use source and load terminal voltages to distinguish the model from observation in this unit.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b362-v16-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入不是現場操作值：I=1500 A, R=0.06 ohm；y=I*R=90 V。只把 I 增加百分之十，y=99 V。模型邊界：直流穩態完整回路；上式只代表本單元明列項，不把它視為完整驗證。","textEn":"Original assumed example, not field operating values: I=1500 A, R=0.06 ohm; y=I*R=90 V. Increasing only I with a ten-percent increase gives y=99 V. Boundary: Complete DC loop in steady state; this equation represents only the explicitly listed term and is not a complete verification.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"依「供電線路壓降」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Feeder voltage drop\", which statement holds?","options":["原創假想算例，輸入不是現場操作值：I=1500 A, R=0.06 ohm；y=I*R=90 V。","本單元絕不可能出現這種失效：忽略源阻抗會得到不合理無限電流","本單元絕不可能出現這種失效：有容量但無連通路徑仍無法供電"],"optionsEn":["Original assumed example, not field operating values: I=1500 A, R=0.06 ohm; y=I*R=90 V.","This unit cannot exhibit the following failure: Omitting source impedance implies unphysical infinite current.","This unit cannot exhibit the following failure: Capacity without connectivity cannot supply the load."],"answer":0,"explanation":"原創假想算例，輸入不是現場操作值：I=1500 A, R=0.06 ohm；y=I*R=90 V。 重算時請保留單位。","explanationEn":"Original assumed example, not field operating values: I=1500 A, R=0.06 ohm; y=I*R=90 V. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":18},{"id":"b362-v16-19","title":"供電線路壓降：試驗與驗證","titleEn":"Feeder voltage drop: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「供電線路壓降」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Feeder voltage drop” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"本單元以源端與負載端電壓區分模型與觀察，先用隔離低壓雙端電壓量測建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「供電線路壓降」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use source and load terminal voltages to distinguish the model from observation in this unit. Establish a baseline using isolated low-voltage measurements at both ends, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Feeder voltage drop. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：重算「供電線路壓降」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出直流穩態完整回路如何限制結論。接著設計一組符合模型及一組由只計去路導線會漏掉回流壓降造成偏離的合成觀察，以源端與負載端電壓說明哪個證據能分辨兩者，保留單位及有效位數。","observationEn":"Site practice: Recalculate the baseline and specified single-input perturbation for Feeder voltage drop, plot the input-output relationship, and explain the limiting assumption: Complete DC loop in steady state. Construct one synthetic observation consistent with the model and another affected by this failure: Counting only the outgoing conductor misses return drop. Explain which evidence in source and load terminal voltages distinguishes them, keeping units and justified significant figures throughout.","failure":"注意干擾：只計去路導線會漏掉回流壓降。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Counting only the outgoing conductor misses return drop. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b362-v16-19-k1","title":"驗證方法","titleEn":"Verification method","text":"本單元以源端與負載端電壓區分模型與觀察，先用隔離低壓雙端電壓量測建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「供電線路壓降」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。","textEn":"Use source and load terminal voltages to distinguish the model from observation in this unit. Establish a baseline using isolated low-voltage measurements at both ends, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Feeder voltage drop. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-19-k2","title":"現場實務","titleEn":"Site practice","text":"重算「供電線路壓降」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出直流穩態完整回路如何限制結論。接著設計一組符合模型及一組由只計去路導線會漏掉回流壓降造成偏離的合成觀察，以源端與負載端電壓說明哪個證據能分辨兩者，保留單位及有效位數。","textEn":"Recalculate the baseline and specified single-input perturbation for Feeder voltage drop, plot the input-output relationship, and explain the limiting assumption: Complete DC loop in steady state. Construct one synthetic observation consistent with the model and another affected by this failure: Counting only the outgoing conductor misses return drop. Explain which evidence in source and load terminal voltages distinguishes them, keeping units and justified significant figures throughout.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"要驗證「供電線路壓降」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Feeder voltage drop\"?","options":["允收準則可以等看到量測數據後再決定。","本單元以源端與負載端電壓區分模型與觀察，先用隔離低壓雙端電壓量測建立基準，再保留相同量測位置與工況重複比較。","本單元絕不可能出現這種失效：混用相電壓與線電壓造成比例誤差"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Use source and load terminal voltages to distinguish the model from observation in this unit.","This unit cannot exhibit the following failure: Mixing phase and line voltage creates a scale error."],"answer":1,"explanation":"本單元以源端與負載端電壓區分模型與觀察，先用隔離低壓雙端電壓量測建立基準，再保留相同量測位置與工況重複比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use source and load terminal voltages to distinguish the model from observation in this unit. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":19},{"id":"b362-v16-20","title":"供電線路壓降：失效診斷","titleEn":"Feeder voltage drop: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-19"],"objective":"從症狀倒推「供電線路壓降」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Feeder voltage drop” and propose discriminating checks, corrective actions and prevention.","instruction":"只計去路導線會漏掉回流壓降。這個失效與「供電線路壓降」的量測偏差可能產生相似表象，因此必須同時檢查源端與負載端電壓，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Counting only the outgoing conductor misses return drop. This failure and a measurement bias in Feeder voltage drop can produce similar symptoms. Cross-check source and load terminal voltages rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：使用源端與負載端電壓作量測證據，才能檢查方程是否對應此處的實際物理量；只計去路導線會漏掉回流壓降，因此應把該原因與量測偏差分開。","observationEn":"Link to the mechanism: Counting only the outgoing conductor misses return drop; separate that causal mechanism from bias in the measurement chain.","failure":"誤判風險：若相信「本單元絕不可能出現這種失效：只計去路導線會漏掉回流壓降」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"This unit cannot exhibit the following failure: Counting only the outgoing conductor misses return drop.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b362-v16-20-k1","title":"失效模式","titleEn":"Failure mode","text":"只計去路導線會漏掉回流壓降。這個失效與「供電線路壓降」的量測偏差可能產生相似表象，因此必須同時檢查源端與負載端電壓，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。","textEn":"Counting only the outgoing conductor misses return drop. This failure and a measurement bias in Feeder voltage drop can produce similar symptoms. Cross-check source and load terminal voltages rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"在「供電線路壓降」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Feeder voltage drop\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","本單元絕不可能出現這種失效：輔助負載遺漏會高估整站效率","只計去路導線會漏掉回流壓降。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","This unit cannot exhibit the following failure: Omitted auxiliary loads overstate station efficiency.","Counting only the outgoing conductor misses return drop."],"answer":2,"explanation":"只計去路導線會漏掉回流壓降。 需以量測區分可能原因。","explanationEn":"Counting only the outgoing conductor misses return drop. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":20},{"id":"b362-v16-21","title":"設備效率能量帳：機制與系統路徑","titleEn":"Equipment efficiency energy account: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-20"],"objective":"說明「設備效率能量帳」如何影響牽引變電所整合的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Equipment efficiency energy account” governs forces, deformation, flow or signals in “Traction-substation integration”, and map the relevant inputs, transfer paths and boundaries.","instruction":"效率連結相同邊界與時窗的輸入輸出能量。本模型把 Ein 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 1067 kWh。這個比較描述明列方程的局部敏感度，不能把相關變數也一起改變後仍稱為相同測試。固定效率與同時窗。使用兩側電能積分作量測證據，才能檢查方程是否對應此處的實際物理量；輔助負載遺漏會高估整站效率，因此應把該原因與量測偏差分開。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「設備效率能量帳」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Efficiency relates input and output energy on the same boundary and window. In this model, Ein is deliberately changed while every other input is held fixed. A ten-percent increase means the output increases to 1067 kWh. This comparison describes the sensitivity of the stated equation; changing correlated variables at the same time would be a different experiment. Fixed efficiency over one common window. Use energy integration at both terminals as measurement evidence that the equation represents the intended physical quantity. Omitted auxiliary loads overstate station efficiency; separate that causal mechanism from bias in the measurement chain. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Equipment efficiency energy account” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入不是現場操作值：Ein=1000 kWh, eta=0.97 1；y=Ein*eta=970 kWh。","observationEn":"Order-of-magnitude cue: Original assumed example, not field operating values: Ein=1000 kWh, eta=0.97 1; y=Ein*eta=970 kWh.","failure":"常見誤解：「本單元絕不可能出現這種失效：輔助負載遺漏會高估整站效率」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"This unit cannot exhibit the following failure: Omitted auxiliary loads overstate station efficiency.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「設備效率能量帳」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Equipment efficiency energy account”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b362-v16-21-k1","title":"設備效率能量帳","titleEn":"Equipment efficiency energy account","text":"效率連結相同邊界與時窗的輸入輸出能量。本模型把 Ein 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 1067 kWh。","textEn":"Efficiency relates input and output energy on the same boundary and window. In this model, Ein is deliberately changed while every other input is held fixed.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：本單元絕不可能出現這種失效：輔助負載遺漏會高估整站效率 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: This unit cannot exhibit the following failure: Omitted auxiliary loads overstate station efficiency. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"關於「設備效率能量帳」，下列哪一項敘述正確？","questionEn":"Which statement about \"Equipment efficiency energy account\" is correct?","options":["效率連結相同邊界與時窗的輸入輸出能量。","本單元絕不可能出現這種失效：輔助負載遺漏會高估整站效率","本單元絕不可能出現這種失效：時窗對齊不同可改變記錄尖峰"],"optionsEn":["Efficiency relates input and output energy on the same boundary and window.","This unit cannot exhibit the following failure: Omitted auxiliary loads overstate station efficiency.","This unit cannot exhibit the following failure: Different window alignment changes recorded peaks."],"answer":0,"explanation":"效率連結相同邊界與時窗的輸入輸出能量。 其餘選項是常見誤解。","explanationEn":"Efficiency relates input and output energy on the same boundary and window. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":21},{"id":"b362-v16-22","title":"設備效率能量帳：定量估算","titleEn":"Equipment efficiency energy account: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-21"],"objective":"以數值模型估算「設備效率能量帳」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Equipment efficiency energy account” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入不是現場操作值：Ein=1000 kWh, eta=0.97 1；y=Ein*eta=970 kWh。只把 Ein 增加百分之十，y=1067 kWh。模型邊界：固定效率與同時窗；上式只代表本單元明列項，不把它視為完整驗證。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original assumed example, not field operating values: Ein=1000 kWh, eta=0.97 1; y=Ein*eta=970 kWh. Increasing only Ein with a ten-percent increase gives y=1067 kWh. Boundary: Fixed efficiency over one common window; this equation represents only the explicitly listed term and is not a complete verification. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：本單元以兩側電能積分區分模型與觀察，先用合成電表資料與輔機帳建立基準，再保留相同量測位置與工況重複比較。","observationEn":"How to cross-check: Use energy integration at both terminals to distinguish the model from observation in this unit.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b362-v16-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入不是現場操作值：Ein=1000 kWh, eta=0.97 1；y=Ein*eta=970 kWh。只把 Ein 增加百分之十，y=1067 kWh。模型邊界：固定效率與同時窗；上式只代表本單元明列項，不把它視為完整驗證。","textEn":"Original assumed example, not field operating values: Ein=1000 kWh, eta=0.97 1; y=Ein*eta=970 kWh. Increasing only Ein with a ten-percent increase gives y=1067 kWh. Boundary: Fixed efficiency over one common window; this equation represents only the explicitly listed term and is not a complete verification.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"依「設備效率能量帳」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Equipment efficiency energy account\", which statement holds?","options":["本單元絕不可能出現這種失效：鬆動接點會提高局部發熱","原創假想算例，輸入不是現場操作值：Ein=1000 kWh, eta=0.97 1；y=Ein*eta=970 kWh。","本單元絕不可能出現這種失效：負載壓降使實測值偏離理想比"],"optionsEn":["This unit cannot exhibit the following failure: A loose joint raises local heating.","Original assumed example, not field operating values: Ein=1000 kWh, eta=0.97 1; y=Ein*eta=970 kWh.","This unit cannot exhibit the following failure: Load voltage drop separates measured voltage from the ideal ratio."],"answer":1,"explanation":"原創假想算例，輸入不是現場操作值：Ein=1000 kWh, eta=0.97 1；y=Ein*eta=970 kWh。 重算時請保留單位。","explanationEn":"Original assumed example, not field operating values: Ein=1000 kWh, eta=0.97 1; y=Ein*eta=970 kWh. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":22},{"id":"b362-v16-23","title":"設備效率能量帳：試驗與驗證","titleEn":"Equipment efficiency energy account: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「設備效率能量帳」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Equipment efficiency energy account” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"本單元以兩側電能積分區分模型與觀察，先用合成電表資料與輔機帳建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「設備效率能量帳」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use energy integration at both terminals to distinguish the model from observation in this unit. Establish a baseline using synthetic meter records and auxiliary ledger, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Equipment efficiency energy account. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：重算「設備效率能量帳」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出固定效率與同時窗如何限制結論。接著設計一組符合模型及一組由輔助負載遺漏會高估整站效率造成偏離的合成觀察，以兩側電能積分說明哪個證據能分辨兩者，保留單位及有效位數。","observationEn":"Site practice: Recalculate the baseline and specified single-input perturbation for Equipment efficiency energy account, plot the input-output relationship, and explain the limiting assumption: Fixed efficiency over one common window. Construct one synthetic observation consistent with the model and another affected by this failure: Omitted auxiliary loads overstate station efficiency. Explain which evidence in energy integration at both terminals distinguishes them, keeping units and justified significant figures throughout.","failure":"注意干擾：輔助負載遺漏會高估整站效率。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Omitted auxiliary loads overstate station efficiency. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b362-v16-23-k1","title":"驗證方法","titleEn":"Verification method","text":"本單元以兩側電能積分區分模型與觀察，先用合成電表資料與輔機帳建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「設備效率能量帳」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。","textEn":"Use energy integration at both terminals to distinguish the model from observation in this unit. Establish a baseline using synthetic meter records and auxiliary ledger, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Equipment efficiency energy account. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-23-k2","title":"現場實務","titleEn":"Site practice","text":"重算「設備效率能量帳」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出固定效率與同時窗如何限制結論。接著設計一組符合模型及一組由輔助負載遺漏會高估整站效率造成偏離的合成觀察，以兩側電能積分說明哪個證據能分辨兩者，保留單位及有效位數。","textEn":"Recalculate the baseline and specified single-input perturbation for Equipment efficiency energy account, plot the input-output relationship, and explain the limiting assumption: Fixed efficiency over one common window. Construct one synthetic observation consistent with the model and another affected by this failure: Omitted auxiliary loads overstate station efficiency. Explain which evidence in energy integration at both terminals distinguishes them, keeping units and justified significant figures throughout.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"要驗證「設備效率能量帳」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Equipment efficiency energy account\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","本單元絕不可能出現這種失效：畸變功因不能只用相位角描述","本單元以兩側電能積分區分模型與觀察，先用合成電表資料與輔機帳建立基準，再保留相同量測位置與工況重複比較。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","This unit cannot exhibit the following failure: Distortion power factor is not described by phase angle alone.","Use energy integration at both terminals to distinguish the model from observation in this unit."],"answer":2,"explanation":"本單元以兩側電能積分區分模型與觀察，先用合成電表資料與輔機帳建立基準，再保留相同量測位置與工況重複比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use energy integration at both terminals to distinguish the model from observation in this unit. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":23},{"id":"b362-v16-24","title":"設備效率能量帳：失效診斷","titleEn":"Equipment efficiency energy account: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-23"],"objective":"從症狀倒推「設備效率能量帳」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Equipment efficiency energy account” and propose discriminating checks, corrective actions and prevention.","instruction":"輔助負載遺漏會高估整站效率。這個失效與「設備效率能量帳」的量測偏差可能產生相似表象，因此必須同時檢查兩側電能積分，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Omitted auxiliary loads overstate station efficiency. This failure and a measurement bias in Equipment efficiency energy account can produce similar symptoms. Cross-check energy integration at both terminals rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：使用兩側電能積分作量測證據，才能檢查方程是否對應此處的實際物理量；輔助負載遺漏會高估整站效率，因此應把該原因與量測偏差分開。","observationEn":"Link to the mechanism: Omitted auxiliary loads overstate station efficiency; separate that causal mechanism from bias in the measurement chain.","failure":"誤判風險：若相信「本單元絕不可能出現這種失效：輔助負載遺漏會高估整站效率」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"This unit cannot exhibit the following failure: Omitted auxiliary loads overstate station efficiency.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b362-v16-24-k1","title":"失效模式","titleEn":"Failure mode","text":"輔助負載遺漏會高估整站效率。這個失效與「設備效率能量帳」的量測偏差可能產生相似表象，因此必須同時檢查兩側電能積分，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。","textEn":"Omitted auxiliary loads overstate station efficiency. This failure and a measurement bias in Equipment efficiency energy account can produce similar symptoms. Cross-check energy integration at both terminals rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"在「設備效率能量帳」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Equipment efficiency energy account\" shows distress, which diagnosis is most reasonable?","options":["輔助負載遺漏會高估整站效率。","只要結構還沒倒，就代表安全餘裕仍然足夠。","本單元絕不可能出現這種失效：時窗對齊不同可改變記錄尖峰"],"optionsEn":["Omitted auxiliary loads overstate station efficiency.","As long as the structure is still standing, its safety margin must still be adequate.","This unit cannot exhibit the following failure: Different window alignment changes recorded peaks."],"answer":0,"explanation":"輔助負載遺漏會高估整站效率。 需以量測區分可能原因。","explanationEn":"Omitted auxiliary loads overstate station efficiency. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":24}],"order":3},{"id":"b362-v16-s4","title":"尖峰需求滑動平均與短路等效電流","titleEn":"Moving-average peak demand & Equivalent short-circuit current","description":"本階段聚焦「尖峰需求滑動平均」與「短路等效電流」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Moving-average peak demand\" and \"Equivalent short-circuit current\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b362-v16-25","title":"尖峰需求滑動平均：機制與系統路徑","titleEn":"Moving-average peak demand: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-24"],"objective":"說明「尖峰需求滑動平均」如何影響牽引變電所整合的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Moving-average peak demand” governs forces, deformation, flow or signals in “Traction-substation integration”, and map the relevant inputs, transfer paths and boundaries.","instruction":"需量是指定時窗能量除時間而非瞬時功率。本模型把 E 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 2640 kW。這個比較描述明列方程的局部敏感度，不能把相關變數也一起改變後仍稱為相同測試。固定十五分鐘觀察窗。使用滑動時窗與電能作量測證據，才能檢查方程是否對應此處的實際物理量；時窗對齊不同可改變記錄尖峰，因此應把該原因與量測偏差分開。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「尖峰需求滑動平均」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Demand divides window energy by duration rather than taking instantaneous power. In this model, E is deliberately changed while every other input is held fixed. A ten-percent increase means the output increases to 2640 kW. This comparison describes the sensitivity of the stated equation; changing correlated variables at the same time would be a different experiment. Specified fifteen-minute observation window. Use moving windows and electrical energy as measurement evidence that the equation represents the intended physical quantity. Different window alignment changes recorded peaks; separate that causal mechanism from bias in the measurement chain. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Moving-average peak demand” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入不是現場操作值：E=600 kWh, minutes=15 min；y=E/(minutes/60)=2400 kW。","observationEn":"Order-of-magnitude cue: Original assumed example, not field operating values: E=600 kWh, minutes=15 min; y=E/(minutes/60)=2400 kW.","failure":"常見誤解：「本單元絕不可能出現這種失效：時窗對齊不同可改變記錄尖峰」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"This unit cannot exhibit the following failure: Different window alignment changes recorded peaks.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「尖峰需求滑動平均」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Moving-average peak demand”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b362-v16-25-k1","title":"尖峰需求滑動平均","titleEn":"Moving-average peak demand","text":"需量是指定時窗能量除時間而非瞬時功率。本模型把 E 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 2640 kW。","textEn":"Demand divides window energy by duration rather than taking instantaneous power. In this model, E is deliberately changed while every other input is held fixed.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：本單元絕不可能出現這種失效：時窗對齊不同可改變記錄尖峰 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: This unit cannot exhibit the following failure: Different window alignment changes recorded peaks. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"關於「尖峰需求滑動平均」，下列哪一項敘述正確？","questionEn":"Which statement about \"Moving-average peak demand\" is correct?","options":["本單元絕不可能出現這種失效：時窗對齊不同可改變記錄尖峰","需量是指定時窗能量除時間而非瞬時功率。","本單元絕不可能出現這種失效：忽略源阻抗會得到不合理無限電流"],"optionsEn":["This unit cannot exhibit the following failure: Different window alignment changes recorded peaks.","Demand divides window energy by duration rather than taking instantaneous power.","This unit cannot exhibit the following failure: Omitting source impedance implies unphysical infinite current."],"answer":1,"explanation":"需量是指定時窗能量除時間而非瞬時功率。 其餘選項是常見誤解。","explanationEn":"Demand divides window energy by duration rather than taking instantaneous power. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b362-v16-26","title":"尖峰需求滑動平均：定量估算","titleEn":"Moving-average peak demand: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-25"],"objective":"以數值模型估算「尖峰需求滑動平均」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Moving-average peak demand” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入不是現場操作值：E=600 kWh, minutes=15 min；y=E/(minutes/60)=2400 kW。只把 E 增加百分之十，y=2640 kW。模型邊界：固定十五分鐘觀察窗；上式只代表本單元明列項，不把它視為完整驗證。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original assumed example, not field operating values: E=600 kWh, minutes=15 min; y=E/(minutes/60)=2400 kW. Increasing only E with a ten-percent increase gives y=2640 kW. Boundary: Specified fifteen-minute observation window; this equation represents only the explicitly listed term and is not a complete verification. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：本單元以滑動時窗與電能區分模型與觀察，先用合成分鐘電能時間序列建立基準，再保留相同量測位置與工況重複比較。","observationEn":"How to cross-check: Use moving windows and electrical energy to distinguish the model from observation in this unit.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b362-v16-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入不是現場操作值：E=600 kWh, minutes=15 min；y=E/(minutes/60)=2400 kW。只把 E 增加百分之十，y=2640 kW。模型邊界：固定十五分鐘觀察窗；上式只代表本單元明列項，不把它視為完整驗證。","textEn":"Original assumed example, not field operating values: E=600 kWh, minutes=15 min; y=E/(minutes/60)=2400 kW. Increasing only E with a ten-percent increase gives y=2640 kW. Boundary: Specified fifteen-minute observation window; this equation represents only the explicitly listed term and is not a complete verification.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"依「尖峰需求滑動平均」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Moving-average peak demand\", which statement holds?","options":["本單元絕不可能出現這種失效：有容量但無連通路徑仍無法供電","本單元絕不可能出現這種失效：混用相電壓與線電壓造成比例誤差","原創假想算例，輸入不是現場操作值：E=600 kWh, minutes=15 min；y=E/(minutes/60)=2400 kW。"],"optionsEn":["This unit cannot exhibit the following failure: Capacity without connectivity cannot supply the load.","This unit cannot exhibit the following failure: Mixing phase and line voltage creates a scale error.","Original assumed example, not field operating values: E=600 kWh, minutes=15 min; y=E/(minutes/60)=2400 kW."],"answer":2,"explanation":"原創假想算例，輸入不是現場操作值：E=600 kWh, minutes=15 min；y=E/(minutes/60)=2400 kW。 重算時請保留單位。","explanationEn":"Original assumed example, not field operating values: E=600 kWh, minutes=15 min; y=E/(minutes/60)=2400 kW. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":26},{"id":"b362-v16-27","title":"尖峰需求滑動平均：試驗與驗證","titleEn":"Moving-average peak demand: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「尖峰需求滑動平均」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Moving-average peak demand” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"本單元以滑動時窗與電能區分模型與觀察，先用合成分鐘電能時間序列建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「尖峰需求滑動平均」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use moving windows and electrical energy to distinguish the model from observation in this unit. Establish a baseline using synthetic minute-energy time series, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Moving-average peak demand. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：重算「尖峰需求滑動平均」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出固定十五分鐘觀察窗如何限制結論。接著設計一組符合模型及一組由時窗對齊不同可改變記錄尖峰造成偏離的合成觀察，以滑動時窗與電能說明哪個證據能分辨兩者，保留單位及有效位數。","observationEn":"Site practice: Recalculate the baseline and specified single-input perturbation for Moving-average peak demand, plot the input-output relationship, and explain the limiting assumption: Specified fifteen-minute observation window. Construct one synthetic observation consistent with the model and another affected by this failure: Different window alignment changes recorded peaks. Explain which evidence in moving windows and electrical energy distinguishes them, keeping units and justified significant figures throughout.","failure":"注意干擾：時窗對齊不同可改變記錄尖峰。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Different window alignment changes recorded peaks. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b362-v16-27-k1","title":"驗證方法","titleEn":"Verification method","text":"本單元以滑動時窗與電能區分模型與觀察，先用合成分鐘電能時間序列建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「尖峰需求滑動平均」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。","textEn":"Use moving windows and electrical energy to distinguish the model from observation in this unit. Establish a baseline using synthetic minute-energy time series, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Moving-average peak demand. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-27-k2","title":"現場實務","titleEn":"Site practice","text":"重算「尖峰需求滑動平均」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出固定十五分鐘觀察窗如何限制結論。接著設計一組符合模型及一組由時窗對齊不同可改變記錄尖峰造成偏離的合成觀察，以滑動時窗與電能說明哪個證據能分辨兩者，保留單位及有效位數。","textEn":"Recalculate the baseline and specified single-input perturbation for Moving-average peak demand, plot the input-output relationship, and explain the limiting assumption: Specified fifteen-minute observation window. Construct one synthetic observation consistent with the model and another affected by this failure: Different window alignment changes recorded peaks. Explain which evidence in moving windows and electrical energy distinguishes them, keeping units and justified significant figures throughout.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"要驗證「尖峰需求滑動平均」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Moving-average peak demand\"?","options":["本單元以滑動時窗與電能區分模型與觀察，先用合成分鐘電能時間序列建立基準，再保留相同量測位置與工況重複比較。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","本單元絕不可能出現這種失效：換相壓降與元件壓降使真值較低"],"optionsEn":["Use moving windows and electrical energy to distinguish the model from observation in this unit.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","This unit cannot exhibit the following failure: Commutation and device drops reduce the actual value."],"answer":0,"explanation":"本單元以滑動時窗與電能區分模型與觀察，先用合成分鐘電能時間序列建立基準，再保留相同量測位置與工況重複比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use moving windows and electrical energy to distinguish the model from observation in this unit. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":27},{"id":"b362-v16-28","title":"尖峰需求滑動平均：失效診斷","titleEn":"Moving-average peak demand: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-27"],"objective":"從症狀倒推「尖峰需求滑動平均」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Moving-average peak demand” and propose discriminating checks, corrective actions and prevention.","instruction":"時窗對齊不同可改變記錄尖峰。這個失效與「尖峰需求滑動平均」的量測偏差可能產生相似表象，因此必須同時檢查滑動時窗與電能，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Different window alignment changes recorded peaks. This failure and a measurement bias in Moving-average peak demand can produce similar symptoms. Cross-check moving windows and electrical energy rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：使用滑動時窗與電能作量測證據，才能檢查方程是否對應此處的實際物理量；時窗對齊不同可改變記錄尖峰，因此應把該原因與量測偏差分開。","observationEn":"Link to the mechanism: Different window alignment changes recorded peaks; separate that causal mechanism from bias in the measurement chain.","failure":"誤判風險：若相信「本單元絕不可能出現這種失效：時窗對齊不同可改變記錄尖峰」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"This unit cannot exhibit the following failure: Different window alignment changes recorded peaks.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b362-v16-28-k1","title":"失效模式","titleEn":"Failure mode","text":"時窗對齊不同可改變記錄尖峰。這個失效與「尖峰需求滑動平均」的量測偏差可能產生相似表象，因此必須同時檢查滑動時窗與電能，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。","textEn":"Different window alignment changes recorded peaks. This failure and a measurement bias in Moving-average peak demand can produce similar symptoms. Cross-check moving windows and electrical energy rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"在「尖峰需求滑動平均」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Moving-average peak demand\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","時窗對齊不同可改變記錄尖峰。","本單元絕不可能出現這種失效：忽略源阻抗會得到不合理無限電流"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Different window alignment changes recorded peaks.","This unit cannot exhibit the following failure: Omitting source impedance implies unphysical infinite current."],"answer":1,"explanation":"時窗對齊不同可改變記錄尖峰。 需以量測區分可能原因。","explanationEn":"Different window alignment changes recorded peaks. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":28},{"id":"b362-v16-29","title":"短路等效電流：機制與系統路徑","titleEn":"Equivalent short-circuit current: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-28"],"objective":"說明「短路等效電流」如何影響牽引變電所整合的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Equivalent short-circuit current” governs forces, deformation, flow or signals in “Traction-substation integration”, and map the relevant inputs, transfer paths and boundaries.","instruction":"故障電流受等效源阻抗而不只由額定電流決定。本模型把 V 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 11000 A。這個比較描述明列方程的局部敏感度，不能把相關變數也一起改變後仍稱為相同測試。僅離線線性等效幅值，不含直流偏置。使用等效源阻抗與波形作量測證據，才能檢查方程是否對應此處的實際物理量；忽略源阻抗會得到不合理無限電流，因此應把該原因與量測偏差分開。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「短路等效電流」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Fault current depends on source impedance rather than rated current alone. In this model, V is deliberately changed while every other input is held fixed. A ten-percent increase means the output increases to 11000 A. This comparison describes the sensitivity of the stated equation; changing correlated variables at the same time would be a different experiment. Offline linear equivalent magnitude without DC offset. Use equivalent source impedance and waveform as measurement evidence that the equation represents the intended physical quantity. Omitting source impedance implies unphysical infinite current; separate that causal mechanism from bias in the measurement chain. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Equivalent short-circuit current” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入不是現場操作值：V=1000 V, Z=0.1 ohm；y=V/Z=10000 A。","observationEn":"Order-of-magnitude cue: Original assumed example, not field operating values: V=1000 V, Z=0.1 ohm; y=V/Z=10000 A.","failure":"常見誤解：「本單元絕不可能出現這種失效：忽略源阻抗會得到不合理無限電流」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"This unit cannot exhibit the following failure: Omitting source impedance implies unphysical infinite current.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「短路等效電流」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Equivalent short-circuit current”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b362-v16-29-k1","title":"短路等效電流","titleEn":"Equivalent short-circuit current","text":"故障電流受等效源阻抗而不只由額定電流決定。本模型把 V 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 11000 A。","textEn":"Fault current depends on source impedance rather than rated current alone. In this model, V is deliberately changed while every other input is held fixed.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：本單元絕不可能出現這種失效：忽略源阻抗會得到不合理無限電流 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: This unit cannot exhibit the following failure: Omitting source impedance implies unphysical infinite current. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"關於「短路等效電流」，下列哪一項敘述正確？","questionEn":"Which statement about \"Equivalent short-circuit current\" is correct?","options":["本單元絕不可能出現這種失效：忽略源阻抗會得到不合理無限電流","本單元絕不可能出現這種失效：鬆動接點會提高局部發熱","故障電流受等效源阻抗而不只由額定電流決定。"],"optionsEn":["This unit cannot exhibit the following failure: Omitting source impedance implies unphysical infinite current.","This unit cannot exhibit the following failure: A loose joint raises local heating.","Fault current depends on source impedance rather than rated current alone."],"answer":2,"explanation":"故障電流受等效源阻抗而不只由額定電流決定。 其餘選項是常見誤解。","explanationEn":"Fault current depends on source impedance rather than rated current alone. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b362-v16-30","title":"短路等效電流：定量估算","titleEn":"Equivalent short-circuit current: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-29"],"objective":"以數值模型估算「短路等效電流」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Equivalent short-circuit current” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入不是現場操作值：V=1000 V, Z=0.1 ohm；y=V/Z=10000 A。只把 V 增加百分之十，y=11000 A。模型邊界：僅離線線性等效幅值，不含直流偏置；上式只代表本單元明列項，不把它視為完整驗證。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original assumed example, not field operating values: V=1000 V, Z=0.1 ohm; y=V/Z=10000 A. Increasing only V with a ten-percent increase gives y=11000 A. Boundary: Offline linear equivalent magnitude without DC offset; this equation represents only the explicitly listed term and is not a complete verification. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：本單元以等效源阻抗與波形區分模型與觀察，先用紙上戴維寧模型與合成波形建立基準，再保留相同量測位置與工況重複比較。","observationEn":"How to cross-check: Use equivalent source impedance and waveform to distinguish the model from observation in this unit.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b362-v16-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入不是現場操作值：V=1000 V, Z=0.1 ohm；y=V/Z=10000 A。只把 V 增加百分之十，y=11000 A。模型邊界：僅離線線性等效幅值，不含直流偏置；上式只代表本單元明列項，不把它視為完整驗證。","textEn":"Original assumed example, not field operating values: V=1000 V, Z=0.1 ohm; y=V/Z=10000 A. Increasing only V with a ten-percent increase gives y=11000 A. Boundary: Offline linear equivalent magnitude without DC offset; this equation represents only the explicitly listed term and is not a complete verification.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"依「短路等效電流」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Equivalent short-circuit current\", which statement holds?","options":["原創假想算例，輸入不是現場操作值：V=1000 V, Z=0.1 ohm；y=V/Z=10000 A。","本單元絕不可能出現這種失效：負載壓降使實測值偏離理想比","本單元絕不可能出現這種失效：畸變功因不能只用相位角描述"],"optionsEn":["Original assumed example, not field operating values: V=1000 V, Z=0.1 ohm; y=V/Z=10000 A.","This unit cannot exhibit the following failure: Load voltage drop separates measured voltage from the ideal ratio.","This unit cannot exhibit the following failure: Distortion power factor is not described by phase angle alone."],"answer":0,"explanation":"原創假想算例，輸入不是現場操作值：V=1000 V, Z=0.1 ohm；y=V/Z=10000 A。 重算時請保留單位。","explanationEn":"Original assumed example, not field operating values: V=1000 V, Z=0.1 ohm; y=V/Z=10000 A. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":30},{"id":"b362-v16-31","title":"短路等效電流：試驗與驗證","titleEn":"Equivalent short-circuit current: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「短路等效電流」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Equivalent short-circuit current” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"本單元以等效源阻抗與波形區分模型與觀察，先用紙上戴維寧模型與合成波形建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「短路等效電流」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use equivalent source impedance and waveform to distinguish the model from observation in this unit. Establish a baseline using paper Thevenin model and synthetic waveform, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Equivalent short-circuit current. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：重算「短路等效電流」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出僅離線線性等效幅值，不含直流偏置如何限制結論。接著設計一組符合模型及一組由忽略源阻抗會得到不合理無限電流造成偏離的合成觀察，以等效源阻抗與波形說明哪個證據能分辨兩者，保留單位及有效位數。","observationEn":"Site practice: Recalculate the baseline and specified single-input perturbation for Equivalent short-circuit current, plot the input-output relationship, and explain the limiting assumption: Offline linear equivalent magnitude without DC offset. Construct one synthetic observation consistent with the model and another affected by this failure: Omitting source impedance implies unphysical infinite current. Explain which evidence in equivalent source impedance and waveform distinguishes them, keeping units and justified significant figures throughout.","failure":"注意干擾：忽略源阻抗會得到不合理無限電流。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Omitting source impedance implies unphysical infinite current. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b362-v16-31-k1","title":"驗證方法","titleEn":"Verification method","text":"本單元以等效源阻抗與波形區分模型與觀察，先用紙上戴維寧模型與合成波形建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「短路等效電流」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。","textEn":"Use equivalent source impedance and waveform to distinguish the model from observation in this unit. Establish a baseline using paper Thevenin model and synthetic waveform, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Equivalent short-circuit current. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-31-k2","title":"現場實務","titleEn":"Site practice","text":"重算「短路等效電流」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出僅離線線性等效幅值，不含直流偏置如何限制結論。接著設計一組符合模型及一組由忽略源阻抗會得到不合理無限電流造成偏離的合成觀察，以等效源阻抗與波形說明哪個證據能分辨兩者，保留單位及有效位數。","textEn":"Recalculate the baseline and specified single-input perturbation for Equivalent short-circuit current, plot the input-output relationship, and explain the limiting assumption: Offline linear equivalent magnitude without DC offset. Construct one synthetic observation consistent with the model and another affected by this failure: Omitting source impedance implies unphysical infinite current. Explain which evidence in equivalent source impedance and waveform distinguishes them, keeping units and justified significant figures throughout.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"要驗證「短路等效電流」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Equivalent short-circuit current\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","本單元以等效源阻抗與波形區分模型與觀察，先用紙上戴維寧模型與合成波形建立基準，再保留相同量測位置與工況重複比較。","本單元絕不可能出現這種失效：只計去路導線會漏掉回流壓降"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Use equivalent source impedance and waveform to distinguish the model from observation in this unit.","This unit cannot exhibit the following failure: Counting only the outgoing conductor misses return drop."],"answer":1,"explanation":"本單元以等效源阻抗與波形區分模型與觀察，先用紙上戴維寧模型與合成波形建立基準，再保留相同量測位置與工況重複比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use equivalent source impedance and waveform to distinguish the model from observation in this unit. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":31},{"id":"b362-v16-32","title":"短路等效電流：失效診斷","titleEn":"Equivalent short-circuit current: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-31"],"objective":"從症狀倒推「短路等效電流」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Equivalent short-circuit current” and propose discriminating checks, corrective actions and prevention.","instruction":"忽略源阻抗會得到不合理無限電流。這個失效與「短路等效電流」的量測偏差可能產生相似表象，因此必須同時檢查等效源阻抗與波形，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Omitting source impedance implies unphysical infinite current. This failure and a measurement bias in Equivalent short-circuit current can produce similar symptoms. Cross-check equivalent source impedance and waveform rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：使用等效源阻抗與波形作量測證據，才能檢查方程是否對應此處的實際物理量；忽略源阻抗會得到不合理無限電流，因此應把該原因與量測偏差分開。","observationEn":"Link to the mechanism: Omitting source impedance implies unphysical infinite current; separate that causal mechanism from bias in the measurement chain.","failure":"誤判風險：若相信「本單元絕不可能出現這種失效：忽略源阻抗會得到不合理無限電流」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"This unit cannot exhibit the following failure: Omitting source impedance implies unphysical infinite current.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b362-v16-32-k1","title":"失效模式","titleEn":"Failure mode","text":"忽略源阻抗會得到不合理無限電流。這個失效與「短路等效電流」的量測偏差可能產生相似表象，因此必須同時檢查等效源阻抗與波形，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。","textEn":"Omitting source impedance implies unphysical infinite current. This failure and a measurement bias in Equivalent short-circuit current can produce similar symptoms. Cross-check equivalent source impedance and waveform rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"在「短路等效電流」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Equivalent short-circuit current\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","本單元絕不可能出現這種失效：鬆動接點會提高局部發熱","忽略源阻抗會得到不合理無限電流。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","This unit cannot exhibit the following failure: A loose joint raises local heating.","Omitting source impedance implies unphysical infinite current."],"answer":2,"explanation":"忽略源阻抗會得到不合理無限電流。 需以量測區分可能原因。","explanationEn":"Omitting source impedance implies unphysical infinite current. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":32}],"order":4},{"id":"b362-v16-s5","title":"母線熱損耗與備援容量算例","titleEn":"Busbar thermal loss & Redundant-capacity example","description":"本階段聚焦「母線熱損耗」與「備援容量算例」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Busbar thermal loss\" and \"Redundant-capacity example\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b362-v16-33","title":"母線熱損耗：機制與系統路徑","titleEn":"Busbar thermal loss: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-32"],"objective":"說明「母線熱損耗」如何影響牽引變電所整合的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Busbar thermal loss” governs forces, deformation, flow or signals in “Traction-substation integration”, and map the relevant inputs, transfer paths and boundaries.","instruction":"接點小電阻在大電流下仍產生明顯熱量。本模型把 I 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 968 W。這個比較描述明列方程的局部敏感度，不能把相關變數也一起改變後仍稱為相同測試。固定電阻的穩態電損。使用接點電阻與溫升作量測證據，才能檢查方程是否對應此處的實際物理量；鬆動接點會提高局部發熱，因此應把該原因與量測偏差分開。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「母線熱損耗」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Small joint resistance can generate substantial heat at high current. In this model, I is deliberately changed while every other input is held fixed. A ten-percent increase means the output increases to 968 W. This comparison describes the sensitivity of the stated equation; changing correlated variables at the same time would be a different experiment. Steady electrical loss at fixed resistance. Use joint resistance and temperature rise as measurement evidence that the equation represents the intended physical quantity. A loose joint raises local heating; separate that causal mechanism from bias in the measurement chain. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Busbar thermal loss” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入不是現場操作值：I=2000 A, R=0.0002 ohm；y=I**2*R=800 W。","observationEn":"Order-of-magnitude cue: Original assumed example, not field operating values: I=2000 A, R=0.0002 ohm; y=I**2*R=800 W.","failure":"常見誤解：「本單元絕不可能出現這種失效：鬆動接點會提高局部發熱」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"This unit cannot exhibit the following failure: A loose joint raises local heating.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「母線熱損耗」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Busbar thermal loss”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b362-v16-33-k1","title":"母線熱損耗","titleEn":"Busbar thermal loss","text":"接點小電阻在大電流下仍產生明顯熱量。本模型把 I 當成主動改變的輸入，其餘輸入固定；當它增加百分之十，輸出增加為 968 W。","textEn":"Small joint resistance can generate substantial heat at high current. In this model, I is deliberately changed while every other input is held fixed.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：本單元絕不可能出現這種失效：鬆動接點會提高局部發熱 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: This unit cannot exhibit the following failure: A loose joint raises local heating. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"關於「母線熱損耗」，下列哪一項敘述正確？","questionEn":"Which statement about \"Busbar thermal loss\" is correct?","options":["接點小電阻在大電流下仍產生明顯熱量。","本單元絕不可能出現這種失效：鬆動接點會提高局部發熱","本單元絕不可能出現這種失效：有容量但無連通路徑仍無法供電"],"optionsEn":["Small joint resistance can generate substantial heat at high current.","This unit cannot exhibit the following failure: A loose joint raises local heating.","This unit cannot exhibit the following failure: Capacity without connectivity cannot supply the load."],"answer":0,"explanation":"接點小電阻在大電流下仍產生明顯熱量。 其餘選項是常見誤解。","explanationEn":"Small joint resistance can generate substantial heat at high current. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b362-v16-34","title":"母線熱損耗：定量估算","titleEn":"Busbar thermal loss: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-33"],"objective":"以數值模型估算「母線熱損耗」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Busbar thermal loss” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入不是現場操作值：I=2000 A, R=0.0002 ohm；y=I**2*R=800 W。只把 I 增加百分之十，y=968 W。模型邊界：固定電阻的穩態電損；上式只代表本單元明列項，不把它視為完整驗證。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original assumed example, not field operating values: I=2000 A, R=0.0002 ohm; y=I**2*R=800 W. Increasing only I with a ten-percent increase gives y=968 W. Boundary: Steady electrical loss at fixed resistance; this equation represents only the explicitly listed term and is not a complete verification. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：本單元以接點電阻與溫升區分模型與觀察，先用低壓四線模型與熱感測建立基準，再保留相同量測位置與工況重複比較。","observationEn":"How to cross-check: Use joint resistance and temperature rise to distinguish the model from observation in this unit.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b362-v16-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入不是現場操作值：I=2000 A, R=0.0002 ohm；y=I**2*R=800 W。只把 I 增加百分之十，y=968 W。模型邊界：固定電阻的穩態電損；上式只代表本單元明列項，不把它視為完整驗證。","textEn":"Original assumed example, not field operating values: I=2000 A, R=0.0002 ohm; y=I**2*R=800 W. Increasing only I with a ten-percent increase gives y=968 W. Boundary: Steady electrical loss at fixed resistance; this equation represents only the explicitly listed term and is not a complete verification.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"依「母線熱損耗」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Busbar thermal loss\", which statement holds?","options":["本單元絕不可能出現這種失效：混用相電壓與線電壓造成比例誤差","原創假想算例，輸入不是現場操作值：I=2000 A, R=0.0002 ohm；y=I**2*R=800 W。","本單元絕不可能出現這種失效：換相壓降與元件壓降使真值較低"],"optionsEn":["This unit cannot exhibit the following failure: Mixing phase and line voltage creates a scale error.","Original assumed example, not field operating values: I=2000 A, R=0.0002 ohm; y=I**2*R=800 W.","This unit cannot exhibit the following failure: Commutation and device drops reduce the actual value."],"answer":1,"explanation":"原創假想算例，輸入不是現場操作值：I=2000 A, R=0.0002 ohm；y=I**2*R=800 W。 重算時請保留單位。","explanationEn":"Original assumed example, not field operating values: I=2000 A, R=0.0002 ohm; y=I**2*R=800 W. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":34},{"id":"b362-v16-35","title":"母線熱損耗：試驗與驗證","titleEn":"Busbar thermal loss: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「母線熱損耗」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Busbar thermal loss” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"本單元以接點電阻與溫升區分模型與觀察，先用低壓四線模型與熱感測建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「母線熱損耗」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use joint resistance and temperature rise to distinguish the model from observation in this unit. Establish a baseline using low-voltage four-wire model and thermal sensing, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Busbar thermal loss. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：重算「母線熱損耗」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出固定電阻的穩態電損如何限制結論。接著設計一組符合模型及一組由鬆動接點會提高局部發熱造成偏離的合成觀察，以接點電阻與溫升說明哪個證據能分辨兩者，保留單位及有效位數。","observationEn":"Site practice: Recalculate the baseline and specified single-input perturbation for Busbar thermal loss, plot the input-output relationship, and explain the limiting assumption: Steady electrical loss at fixed resistance. Construct one synthetic observation consistent with the model and another affected by this failure: A loose joint raises local heating. Explain which evidence in joint resistance and temperature rise distinguishes them, keeping units and justified significant figures throughout.","failure":"注意干擾：鬆動接點會提高局部發熱。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A loose joint raises local heating. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b362-v16-35-k1","title":"驗證方法","titleEn":"Verification method","text":"本單元以接點電阻與溫升區分模型與觀察，先用低壓四線模型與熱感測建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「母線熱損耗」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。","textEn":"Use joint resistance and temperature rise to distinguish the model from observation in this unit. Establish a baseline using low-voltage four-wire model and thermal sensing, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Busbar thermal loss. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-35-k2","title":"現場實務","titleEn":"Site practice","text":"重算「母線熱損耗」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出固定電阻的穩態電損如何限制結論。接著設計一組符合模型及一組由鬆動接點會提高局部發熱造成偏離的合成觀察，以接點電阻與溫升說明哪個證據能分辨兩者，保留單位及有效位數。","textEn":"Recalculate the baseline and specified single-input perturbation for Busbar thermal loss, plot the input-output relationship, and explain the limiting assumption: Steady electrical loss at fixed resistance. Construct one synthetic observation consistent with the model and another affected by this failure: A loose joint raises local heating. Explain which evidence in joint resistance and temperature rise distinguishes them, keeping units and justified significant figures throughout.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"要驗證「母線熱損耗」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Busbar thermal loss\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","本單元絕不可能出現這種失效：輔助負載遺漏會高估整站效率","本單元以接點電阻與溫升區分模型與觀察，先用低壓四線模型與熱感測建立基準，再保留相同量測位置與工況重複比較。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","This unit cannot exhibit the following failure: Omitted auxiliary loads overstate station efficiency.","Use joint resistance and temperature rise to distinguish the model from observation in this unit."],"answer":2,"explanation":"本單元以接點電阻與溫升區分模型與觀察，先用低壓四線模型與熱感測建立基準，再保留相同量測位置與工況重複比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use joint resistance and temperature rise to distinguish the model from observation in this unit. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":35},{"id":"b362-v16-36","title":"母線熱損耗：失效診斷","titleEn":"Busbar thermal loss: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-35"],"objective":"從症狀倒推「母線熱損耗」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Busbar thermal loss” and propose discriminating checks, corrective actions and prevention.","instruction":"鬆動接點會提高局部發熱。這個失效與「母線熱損耗」的量測偏差可能產生相似表象，因此必須同時檢查接點電阻與溫升，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A loose joint raises local heating. This failure and a measurement bias in Busbar thermal loss can produce similar symptoms. Cross-check joint resistance and temperature rise rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：使用接點電阻與溫升作量測證據，才能檢查方程是否對應此處的實際物理量；鬆動接點會提高局部發熱，因此應把該原因與量測偏差分開。","observationEn":"Link to the mechanism: A loose joint raises local heating; separate that causal mechanism from bias in the measurement chain.","failure":"誤判風險：若相信「本單元絕不可能出現這種失效：鬆動接點會提高局部發熱」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"This unit cannot exhibit the following failure: A loose joint raises local heating.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b362-v16-36-k1","title":"失效模式","titleEn":"Failure mode","text":"鬆動接點會提高局部發熱。這個失效與「母線熱損耗」的量測偏差可能產生相似表象，因此必須同時檢查接點電阻與溫升，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。","textEn":"A loose joint raises local heating. This failure and a measurement bias in Busbar thermal loss can produce similar symptoms. Cross-check joint resistance and temperature rise rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"在「母線熱損耗」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Busbar thermal loss\" shows distress, which diagnosis is most reasonable?","options":["鬆動接點會提高局部發熱。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","本單元絕不可能出現這種失效：有容量但無連通路徑仍無法供電"],"optionsEn":["A loose joint raises local heating.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","This unit cannot exhibit the following failure: Capacity without connectivity cannot supply the load."],"answer":0,"explanation":"鬆動接點會提高局部發熱。 需以量測區分可能原因。","explanationEn":"A loose joint raises local heating. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":36},{"id":"b362-v16-37","title":"備援容量算例：機制與系統路徑","titleEn":"Redundant-capacity example: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-36"],"objective":"說明「備援容量算例」如何影響牽引變電所整合的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Redundant-capacity example” governs forces, deformation, flow or signals in “Traction-substation integration”, and map the relevant inputs, transfer paths and boundaries.","instruction":"一台不可用時的名義餘量仍須檢查網路供電路徑。本模型把 units 當成主動改變的輸入，其餘輸入固定；當它增加一個整數單位，輸出增加為 14 MVA。這個比較描述明列方程的局部敏感度，不能把相關變數也一起改變後仍稱為相同測試。相同額定單元且可完全分攤。使用供電拓樸與剩餘容量作量測證據，才能檢查方程是否對應此處的實際物理量；有容量但無連通路徑仍無法供電，因此應把該原因與量測偏差分開。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「備援容量算例」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Nominal reserve after one unavailable unit still requires a viable network path. In this model, units is deliberately changed while every other input is held fixed. An increase of one whole unit means the output increases to 14 MVA. This comparison describes the sensitivity of the stated equation; changing correlated variables at the same time would be a different experiment. Equal-rated units with fully shareable loading. Use feeding topology and remaining capacity as measurement evidence that the equation represents the intended physical quantity. Capacity without connectivity cannot supply the load; separate that causal mechanism from bias in the measurement chain. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Redundant-capacity example” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入不是現場操作值：units=3 count, each=10 MVA, load=16 MVA；y=(units-1)*each-load=4 MVA。","observationEn":"Order-of-magnitude cue: Original assumed example, not field operating values: units=3 count, each=10 MVA, load=16 MVA; y=(units-1)*each-load=4 MVA.","failure":"常見誤解：「本單元絕不可能出現這種失效：有容量但無連通路徑仍無法供電」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"This unit cannot exhibit the following failure: Capacity without connectivity cannot supply the load.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「備援容量算例」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Redundant-capacity example”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b362-v16-37-k1","title":"備援容量算例","titleEn":"Redundant-capacity example","text":"一台不可用時的名義餘量仍須檢查網路供電路徑。本模型把 units 當成主動改變的輸入，其餘輸入固定；當它增加一個整數單位，輸出增加為 14 MVA。","textEn":"Nominal reserve after one unavailable unit still requires a viable network path. In this model, units is deliberately changed while every other input is held fixed.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：本單元絕不可能出現這種失效：有容量但無連通路徑仍無法供電 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: This unit cannot exhibit the following failure: Capacity without connectivity cannot supply the load. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"關於「備援容量算例」，下列哪一項敘述正確？","questionEn":"Which statement about \"Redundant-capacity example\" is correct?","options":["本單元絕不可能出現這種失效：有容量但無連通路徑仍無法供電","一台不可用時的名義餘量仍須檢查網路供電路徑。","本單元絕不可能出現這種失效：負載壓降使實測值偏離理想比"],"optionsEn":["This unit cannot exhibit the following failure: Capacity without connectivity cannot supply the load.","Nominal reserve after one unavailable unit still requires a viable network path.","This unit cannot exhibit the following failure: Load voltage drop separates measured voltage from the ideal ratio."],"answer":1,"explanation":"一台不可用時的名義餘量仍須檢查網路供電路徑。 其餘選項是常見誤解。","explanationEn":"Nominal reserve after one unavailable unit still requires a viable network path. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b362-v16-38","title":"備援容量算例：定量估算","titleEn":"Redundant-capacity example: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-37"],"objective":"以數值模型估算「備援容量算例」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Redundant-capacity example” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入不是現場操作值：units=3 count, each=10 MVA, load=16 MVA；y=(units-1)*each-load=4 MVA。只把 units 增加一個整數單位，y=14 MVA。模型邊界：相同額定單元且可完全分攤；上式只代表本單元明列項，不把它視為完整驗證。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original assumed example, not field operating values: units=3 count, each=10 MVA, load=16 MVA; y=(units-1)*each-load=4 MVA. Increasing only units with an increase of one whole unit gives y=14 MVA. Boundary: Equal-rated units with fully shareable loading; this equation represents only the explicitly listed term and is not a complete verification. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：本單元以供電拓樸與剩餘容量區分模型與觀察，先用離線單線圖與情境表建立基準，再保留相同量測位置與工況重複比較。","observationEn":"How to cross-check: Use feeding topology and remaining capacity to distinguish the model from observation in this unit.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b362-v16-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入不是現場操作值：units=3 count, each=10 MVA, load=16 MVA；y=(units-1)*each-load=4 MVA。只把 units 增加一個整數單位，y=14 MVA。模型邊界：相同額定單元且可完全分攤；上式只代表本單元明列項，不把它視為完整驗證。","textEn":"Original assumed example, not field operating values: units=3 count, each=10 MVA, load=16 MVA; y=(units-1)*each-load=4 MVA. Increasing only units with an increase of one whole unit gives y=14 MVA. Boundary: Equal-rated units with fully shareable loading; this equation represents only the explicitly listed term and is not a complete verification.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"依「備援容量算例」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Redundant-capacity example\", which statement holds?","options":["本單元絕不可能出現這種失效：畸變功因不能只用相位角描述","本單元絕不可能出現這種失效：只計去路導線會漏掉回流壓降","原創假想算例，輸入不是現場操作值：units=3 count, each=10 MVA, load=16 MVA。"],"optionsEn":["This unit cannot exhibit the following failure: Distortion power factor is not described by phase angle alone.","This unit cannot exhibit the following failure: Counting only the outgoing conductor misses return drop.","Original assumed example, not field operating values: units=3 count, each=10 MVA, load=16 MVA; y=(units-1)*each-load=4 MVA."],"answer":2,"explanation":"原創假想算例，輸入不是現場操作值：units=3 count, each=10 MVA, load=16 MVA；y=(units-1)*each-load=4 MVA。 重算時請保留單位。","explanationEn":"Original assumed example, not field operating values: units=3 count, each=10 MVA, load=16 MVA; y=(units-1)*each-load=4 MVA. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":38},{"id":"b362-v16-39","title":"備援容量算例：試驗與驗證","titleEn":"Redundant-capacity example: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「備援容量算例」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Redundant-capacity example” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"本單元以供電拓樸與剩餘容量區分模型與觀察，先用離線單線圖與情境表建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「備援容量算例」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use feeding topology and remaining capacity to distinguish the model from observation in this unit. Establish a baseline using offline single-line diagram and scenario table, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Redundant-capacity example. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：重算「備援容量算例」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出相同額定單元且可完全分攤如何限制結論。接著設計一組符合模型及一組由有容量但無連通路徑仍無法供電造成偏離的合成觀察，以供電拓樸與剩餘容量說明哪個證據能分辨兩者，保留單位及有效位數。","observationEn":"Site practice: Recalculate the baseline and specified single-input perturbation for Redundant-capacity example, plot the input-output relationship, and explain the limiting assumption: Equal-rated units with fully shareable loading. Construct one synthetic observation consistent with the model and another affected by this failure: Capacity without connectivity cannot supply the load. Explain which evidence in feeding topology and remaining capacity distinguishes them, keeping units and justified significant figures throughout.","failure":"注意干擾：有容量但無連通路徑仍無法供電。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Capacity without connectivity cannot supply the load. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b362-v16-39-k1","title":"驗證方法","titleEn":"Verification method","text":"本單元以供電拓樸與剩餘容量區分模型與觀察，先用離線單線圖與情境表建立基準，再保留相同量測位置與工況重複比較。將輸入表與輸出表分開保存，記下校正、解析度及時間戳記；至少改變一個輸入並保持其餘條件，檢查結果方向是否符合「備援容量算例」的方程。殘差超出事先設定的教學容差時，先查單位與量測鏈，再查省略的物理項。","textEn":"Use feeding topology and remaining capacity to distinguish the model from observation in this unit. Establish a baseline using offline single-line diagram and scenario table, then repeat at the same locations and conditions. Keep input and output records separate, recording calibration, resolution and timestamps. Change one input while holding others fixed and check the trend predicted by Redundant-capacity example. When residuals exceed a predefined teaching tolerance, examine units and the measurement chain before attributing the difference to omitted physics.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-39-k2","title":"現場實務","titleEn":"Site practice","text":"重算「備援容量算例」的基準與所列單一輸入變動案例，畫出輸入至輸出的關係，並寫出相同額定單元且可完全分攤如何限制結論。接著設計一組符合模型及一組由有容量但無連通路徑仍無法供電造成偏離的合成觀察，以供電拓樸與剩餘容量說明哪個證據能分辨兩者，保留單位及有效位數。","textEn":"Recalculate the baseline and specified single-input perturbation for Redundant-capacity example, plot the input-output relationship, and explain the limiting assumption: Equal-rated units with fully shareable loading. Construct one synthetic observation consistent with the model and another affected by this failure: Capacity without connectivity cannot supply the load. Explain which evidence in feeding topology and remaining capacity distinguishes them, keeping units and justified significant figures throughout.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"要驗證「備援容量算例」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Redundant-capacity example\"?","options":["本單元以供電拓樸與剩餘容量區分模型與觀察，先用離線單線圖與情境表建立基準，再保留相同量測位置與工況重複比較。","不確定度太難估計，報告中只寫最佳值即可。","本單元絕不可能出現這種失效：時窗對齊不同可改變記錄尖峰"],"optionsEn":["Use feeding topology and remaining capacity to distinguish the model from observation in this unit.","Uncertainty is too hard to estimate, so the report may state only the best value.","This unit cannot exhibit the following failure: Different window alignment changes recorded peaks."],"answer":0,"explanation":"本單元以供電拓樸與剩餘容量區分模型與觀察，先用離線單線圖與情境表建立基準，再保留相同量測位置與工況重複比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use feeding topology and remaining capacity to distinguish the model from observation in this unit. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":39},{"id":"b362-v16-40","title":"備援容量算例：失效診斷","titleEn":"Redundant-capacity example: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"prerequisiteIds":["b362-v16-39"],"objective":"從症狀倒推「備援容量算例」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Redundant-capacity example” and propose discriminating checks, corrective actions and prevention.","instruction":"有容量但無連通路徑仍無法供電。這個失效與「備援容量算例」的量測偏差可能產生相似表象，因此必須同時檢查供電拓樸與剩餘容量，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Capacity without connectivity cannot supply the load. This failure and a measurement bias in Redundant-capacity example can produce similar symptoms. Cross-check feeding topology and remaining capacity rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：使用供電拓樸與剩餘容量作量測證據，才能檢查方程是否對應此處的實際物理量；有容量但無連通路徑仍無法供電，因此應把該原因與量測偏差分開。","observationEn":"Link to the mechanism: Capacity without connectivity cannot supply the load; separate that causal mechanism from bias in the measurement chain.","failure":"誤判風險：若相信「本單元絕不可能出現這種失效：有容量但無連通路徑仍無法供電」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"This unit cannot exhibit the following failure: Capacity without connectivity cannot supply the load.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b362-v16-40-k1","title":"失效模式","titleEn":"Failure mode","text":"有容量但無連通路徑仍無法供電。這個失效與「備援容量算例」的量測偏差可能產生相似表象，因此必須同時檢查供電拓樸與剩餘容量，不能只靠一個合成指標判定原因。若資料無法區分兩種假說，結論應保留未確定狀態，並提出下一項可推翻假說的獨立測試。","textEn":"Capacity without connectivity cannot supply the load. This failure and a measurement bias in Redundant-capacity example can produce similar symptoms. Cross-check feeding topology and remaining capacity rather than diagnosing from one aggregate score. If the available observations cannot distinguish the hypotheses, retain an unresolved conclusion and specify an independent test that could falsify one explanation. Repeating the same biased sensor is not independent confirmation.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]},{"id":"b362-v16-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"]}],"quiz":{"question":"在「備援容量算例」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Redundant-capacity example\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","有容量但無連通路徑仍無法供電。","本單元絕不可能出現這種失效：負載壓降使實測值偏離理想比"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Capacity without connectivity cannot supply the load.","This unit cannot exhibit the following failure: Load voltage drop separates measured voltage from the ideal ratio."],"answer":1,"explanation":"有容量但無連通路徑仍無法供電。 需以量測區分可能原因。","explanationEn":"Capacity without connectivity cannot supply the load. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":40}],"order":5}],"sourceIds":["v16s-track-energy","v16s-track-energy-guide","v16s-track-ole","v16s-track-elsafe"],"curriculumVersion":16,"stepCount":40,"estimatedMinutes":1000,"flowDiagram":"assets/diagrams/v16-b362-zh.svg","flowDiagramEn":"assets/diagrams/v16-b362-en.svg"}};
